  FT["BN-S-16-2024-PROCLAMATION-AND-NOTICE-UNDER-ARTICLE-522"] = {"id":"BN-S-16-2024-PROCLAMATION-AND-NOTICE-UNDER-ARTICLE-522","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"依第 522 条发布的宣告与通知","en":"PROCLAMATION AND NOTICE UNDER ARTICLE 522","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-16-2024-PROCLAMATION-AND-NOTICE-UNDER-ARTICLE-522.pdf》（3 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-16-2024-PROCLAMATION-AND-NOTICE-UNDER-ARTICLE-522.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-16-2024-PROCLAMATION-AND-NOTICE-UNDER-ARTICLE-522-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No. S 16\n\nCONSTITUTION OF BRUNEI DARUSSALAM PROCLAMATION AND NOTICE UNDER ARTICLE 52(2)\n\nHIS MAJESTY\n\nTHE SULTAN AND YANG DI-PERTUAN, BRUNEI DARUSSALAM. In the name of ALLAH, the Compassionate, the Merciful, PRAISE be to ALLAH, the Lord of the Universe, and may the benediction and peace of ALLAH be upon Our Leader Muhammad and upon all his Relations and Friends.\n\nBY THE GRACE OF ALLAH, WE, SULTAN HAJI HASSANAL BOLKIAH MU'IZZADDIN WADDAULAH IBNI AL-MARHUM SULTAN HAJI OMAR 'ALI SAIFUDDIEN SA'ADUL KHAIRI WADDIEN, SOVEREIGN AND CHIEF\n\nOF THE ROYAL FAMILY ORDER OF THE CROWN OF BRUNEI, SOVEREIGN AND CHIEF OF THE MOST ESTEEMED FAMILY ORDER LAlLA UTAMA,\n\nSOVEREIGN AND CHIEF OF THE MOST ESTEEMED FAMILY ORDER SERI\n\nUTAMA, SOVEREIGN AND CHIEF OF THE MOST EMINENT ORDER OF\n\nISLAM NEGARA BRUNEI, SOVEREIGN AND CHIEF OF THE MOST ILLUSTRIOUS ORDER OF PADUKA LAlLA JASA KEBERANIAN GEMILANG,\n\nSOVEREIGN AND CHIEF OF THE MOST EXALTED ORDER OF PADUKA KEBERANIAN LAlLA TERBILANG, SOVEREIGN AND CHIEF OF THE MOST\n\nGALLANT ORDER OF PAHLAWAN NEGARA BRUNEI, SOVEREIGN AND\n\nCHIEF OF THE MOST BLESSED ORDER OF SETIA NEGARA BRUNEI,\n\nSOVEREIGN AND CHIEF OF THE MOST DISTINGUISHED ORDER OF PADUKA SERI LAlLA JASA, SOVEREIGN AND CHIEF OF THE MOST\n\nBRUNEI DARUSSALAM GOVERNMENT GAZETTE\n\nHONOURABLE ORDER OF THE CROWN OF BRUNEI, SOVEREIGN AND\n\nCHIEF OF THE MOST FAITHFUL ORDER OF PERWIRA AGONG NEGARA\n\nBRUNEI, HONORARY KNIGHT GRAND CROSS OF THE MOST HONOURABLE ORDER OF THE BATH (UNITED KINGDOM OF GREAT BRITAIN AND NORTHERN IRELAND), HONORARY KNIGHT GRAND CROSS\n\nOF THE MOST DISTINGUISHED ORDER OF SAINT MICHAEL AND SAINT GEORGE (UNITED KINGDOM OF GREAT BRITAIN AND NORTHERN IRELAND), HONORARY COMMANDER OF THE MOST DISTINGUISHED ORDER OF SAINT MICHAEL AND SAINT GEORGE (UNITED KINGDOM OF GREAT BRITAIN AND NORTHERN IRELAND), DARJAH UTAMA SERI MAHKOTA NEGARA (MALAYSIA), COLLAR OF THE SUPREME ORDER OF THE CHRYSANTHEMUM (JAPAN), THE ORDER OF AL-HUSSEIN BIN ALI (HASHEMITE KINGDOM OF JORDAN), THE CIVIL ORDER OF OMAN, FIRST CLASS (SULTANATE OF OMAN), AL-KHALIFIA (KINGDOM OF BAHRAIN), QUISSAM EL MOHAMMDI GRAND COLLIER (KINGDOM OF MOROCCO), THE MOST AUSPICIOUS ORDER OF THE RAJAMITRABHORN (KINGDOM OF THAILAND), THE GREAT COLLAR OF BADR (KINGDOM OF SAUDI ARABIA), KNIGHT OF THE ROYAL ORDER OF THE SERAPHIM (KINGDOM OF SWEDEN), KNIGHT GRAND CROSS OF THE NETHERLANDS (KINGDOM OF THE NETHERLANDS), QILADAT AL-MUBARAK AL-KABIR-COLLAR OF MUBARAK THE GREAT (KUWAIT), GRAND ORDER OF MUGUNGHWA (REPUBLIC OF KOREA), BINTANG REPUBLIK INDONESIA ADIPURNA (REPUBLIC OF INDONESIA), COLLAR OF THE NILE (ARAB REPUBLIC OF EGYPT), THE ORDER OF LAKANDULA WITH THE RANK OF GRAND COLLAR SUPREMO (REPUBLIC OF THE PHILIPPINES), THE ANCIENT ORDER OF SIKATUNA RANK OF RAJAH (REPUBLIC OF THE PHILIPPINES), THE ORDER OF TEMASEK, FIRST CLASS (REPUBLIC OF SINGAPORE), NISHAN-E-PAKISTAN (REPUBLIC ISLAM PAKISTAN), GRAND CROIX LEGION D'HONNEUR (REPUBLIC OF FRANCE), GRAND CROSS SPECIAL CLASS OF THE ORDER OF MERIT (FEDERAL REPUBLIC OF GERMANY), THE ORDER OF MERIT, FIRST CLASS (UKRAINE), THE ORDER OF PRINCE YAROSLAV THE WISE, FIRST CLASS (UKRAINE), PHOXAY LANE XANG (LAO PEOPLE'S DEMOCRATIC REPUBLIC), THE MOST EXALTED ROYAL FAMILY ORDER OF KELANTAN (KELANTAN), THE MOST ESTEEMED ROYAL FAMILY ORDER OF JOHOR (JOHOR), THE MOST EXALTED ROYAL FAMILY ORDER OF NEGERI SEMBILAN (NEGERI SEMBILAN), THE MOST ESTEEMED ROYAL FAMILY ORDER OF SRI INDERA MAHKOTA PAHANG (PAHANG), THE MOST EXALTED ROYAL FAMILY ORDER OF SELANGOR (SELANGOR), THE ROYAL FAMILY ORDER OF SYED PUTRA (PERLIS), THE MOST ESTEEMED ROYAL FAMILY ORDER OF PERAK (PERAK), THE MOST EXALTED SUPREME ROYAL FAMILY ORDER OF TERENGGANU (TERENGGANU), THE MOST ESTEEMED ROYAL FAMILY ORDER OF KEDAR (KEDAR), THE MOST EXALTED ORDER OF STAR OF SARAWAK (SARAWAK), SERI PANGLIMA DARJAH KINABALU (SABAH), DARJAH KEPAHLAWANAN ANGKATAN TENTERA -PANGLIMA GAGAH ANGKATAN TENTERA (MALAYSIA), THE DISTINGUISHED SERVICE ORDER (MILITARY) (REPUBLIC OF SINGAPORE), THE PHILIPPINES LEGION OF HONOUR (DEGREE OF CHIEF COMMANDER) (REPUBLIC OF THE PHILIPPINES), THE CROSS OF HONOUR FOR FAITH AND FAITHFULNESS TO THE STATE (UKRAINE), the Sultan and Yang Di-Pertuan of the Sovereign State and Territory of Brunei Darussalam and all its Dependencies. TO ALL TO WHOM THESE PRESENTS shall come. GREETINGS: WHEREAS by Article 52(1) of the Constitution of Brunei Darussalam, it is provided that unless otherwise directed by His Majesty the Sultan and Yang Di-Pertuan, there shall be a session of the Legislative Council once at least in every year, so that a period of more than 12 months shall not intervene between the last sitting in one session and the date appointed for its first sitting in the next session. AND WHEREAS by Article 52(2) of the Constitution of Brunei Darussalam, it is provided that each session of the Legislative Council shall be held at such place and shall commence and end at such time as His Majesty the Sultan and Yang Di-Pertuan may, from time to time, by notice published in the Gazette, appoint. NOW THEREFORE WE in exercise of the powers conferred upon US by the Constitution of Brunei Darussalam do hereby appoint the 17th day of Sya'aban 1445 Hijriah corresponding to the 27th day of February 2024, to be the date for the commencement of a session of the Legislative Council to be held at the Dewan Persidangan Majlis Mesyuarat Negara, Dewan Majlis, Jalan Dewan Majlis, Bandar Seri Begawan, Brunei Darussalam at 9.00 o'clock in the forenoon. Done at OUR Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam this 11th. day of Sya'aban, 1445 Hijriah corresponding to the 21st. day of February, 2024, being the fifty-seventh year of OUR Reign in Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"PROCLAMATION AND NOTICE UNDER ARTICLE 522","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-17-2004-NOTIFICATION-OF-COMMENCEMENT"] = {"id":"BN-S-17-2004-NOTIFICATION-OF-COMMENCEMENT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"生效公告","en":"NOTIFICATION OF COMMENCEMENT","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-17-2004-NOTIFICATION-OF-COMMENCEMENT.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-17-2004-NOTIFICATION-OF-COMMENCEMENT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-17-2004-NOTIFICATION-OF-COMMENCEMENT-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"12th. FEBRUARY, 2004 No. S 17\n\nCURRENCY AND MONETARY ORDER, 2004 Notiftcation of Commencement In exercise of the power conferred by subsection (1) of section 1, the Minister of Finance, with the approval of His Majesty the Sultan and Yang Di-Pertuan, hereby appoints 1st. February, 2004 as the date on which the Currency and Monetary Order, 2004 shall commence. Dated this 4th. day of Zulhijjah, 1424 Hijriah corresponding to the 26th. day of January, 2004.\n\nDATO PADUKA AWANG HAJI ABDUL RAHMAN BIN HAJI IBRAHIM Permanent Secretary, Ministry of Finance, Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"NOTIFICATION OF COMMENCEMENT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
