  FT["BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014"] = {"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":25,"structureMode":"SECTION","title":{"zh":"都东市政局常设命令附例 2014","en":"TUTONG MUNICIPAL BOARD STANDING ORDERS BY LAWS 2014","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014.pdf》（7 页），本次切分 25 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These By-Laws may be cited as the Thtong Municipal Board (Standing Orders) By-Laws, 2014."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these By-Laws, unless the context requires otherwise - means the Thtong Municipal Board; means any meeting of the Board; means member of the Board; means the person appointed by the Chairman to be the secretary; \"working day\" means any day other than a Friday, Sunday or public holiday.\n\nOF BOARD"}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The procedure prescribed under these By-Laws shall be observed for the and conduct of business of the Board and any of its committee. time and place of meetings."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Board shall convene as often as may be required, but in any case, it shall meet at least six times a year at such time and place as may be notified by the of meetings."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Chairman shall cause notice of the meeting to be given to members not less than 7 days prior to the date of the meeting: Provided that accidental omission to give such notice shall not invalidate any proceedings at any such meetings. Provided further that in a case of urgency, the Chairman may direct that notice to be disposed with. Doa."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All meetings of the Board shall open with a doa.\n\nOF PROCEEDINGS"}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(1) At a meeting, two-thirds of the members shall form a quorum.\n\n(2) No business of the Board shall be transacted at any meeting thereof unless a quorum is present. to preside."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"[1) As soon as a quorum is present, the Chairman shall take the chair and call the members to order.\n\n(2) The Chairman shall preside at any meeting of the Board and shall have the general control of all deliberations and proceedings of the meeting.\n\n(3) If the Chairman is absent or for any other reason is unable to discharge the members present may elect one of them to preside at the of secretary."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The secretary shall, under the direction of the Chairman, have charge of all and documents of the Board and shall in all other respects carry out such duties as may be imposed upon him by these By-Laws or assigned to him by direction of the Chairman."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"(1) The secretary shall keep minutes of all meetings.\n\n(2) As soon as possible after every meeting, a copy of the draft minutes shall be sent to members. If on confirmation such draft minutes are amended, the Chairman shall forthwith be informed of the amendments made. of meeting."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Chairman of a meeting may, with consent of the members, adjourn the of quorum."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"If there is no quorum present within one-half hour after the time appointed the secretary shall take down the names of the members then and the meeting shall be adjourned to such day as the Chairman may appoint, being not less than 7 nor more than 21 days after the day first appointed. to preserve order and decorum."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Chairman shall preserve order and decorum and shall decide all question of order subject to an appeal by any member. of precedence in speaking."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"When two or more members arise to speak at the same time, the Chairman name the· member who, in his opinion, has right of precedence. to address Chairman while speaking."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Every member while speaking shall respectfully address the Chairman. word or epithet not to be used."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"No member shall {a} apply any offensive word or epithet to the Board or any member; or {b} speak outside the question under debate. speaking not to be interrupted except on point of order."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"When a member is speaking or a question is being put, no member shall hold any private discourse, or make any noise or disturbance, or interrupt a speaker except to raise a point of order. to speak once only on same question."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"No member shall speak more than once on the same question without the the Chairman, except a member who has made a substantive motion who be allowed a reply. No member shall speak on the same question, or in reply, for longer than 5 minutes. or enquiries relating to by-law etc."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Question or enquiries may be put to the Chairman or through him to any relating to any by-law, motion or other matter connected with the of the Board, but no argument or opinion is to be offered or facts to be stated. member present to vote."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"(1) member, who shall be present in the meeting when a motion is put, shall have the right to vote thereon, unless he is disqualified by interest, in which case he shall not vote.\n\n(2) Any member who is directly or indirectly interested with respect to any shall disclose the nature of his interest after the relevant facts of the has come to his know ledge.\n\n(3) A disclosure under sub-by-law (2) shall be recorded in the minutes of and after the disclosure, the member shall be disqualified from taking part in any deliberation or decision of the Board with respect to that motion."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"All motions arising at any meeting shall be decided by a majority of votes of the members present and, in the case of an equality of votes, the Chairman or, in his absence, the member acting as Chairman, shall have a casting vote.\n\nOF THE DAY of the day."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"The secretary shall notify the members in the meetings \"The General Orders of the day\" as follows - {a) confirmation of the agenda; {b) presentation and consideration of reports; {c) motions; {d) the giving of notices of motion; {e) confirmation of the minutes of meeting; {f) any other businesses arising from the meeting. of motions."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Notice of all motions introducing any new matter shall be given within 5 working days, and all motions shall be placed in \"The General Orders of the day\". in writing and seconded."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A24","no":24,"noLabel":{"en":"Section 24."},"heading":{"en":"10th. FEBRUARY, 2014"},"text":{"en":"Every motion shall be in writing and read by the Chairman, but shall be seconded before being put or debated. recorded."}},{"id":"BN-S-2-2014-TUTONG-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2014-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"All motions shall be recorded by the secretary together with the voting Made this 26th. day of Rabiulawal, 1435 Hijriah corresponding to the 28th. day of January, 2014.\n\nHAJI ALI BIN MATYASSIN Thtong Municipal Board. this 26th. day of Rabiulawal, 1435 Hijriah corresponding to the 28th. day of January, 2014.\n\nPEHIN UDANA KHATIB DATO PADUKA SERI SETIA\n\nUSTAZ HAJI AWANG BADARUDDIN BIN\n\nDATO PADUKA HAJI OTHMAN Home Affairs, Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"TUTONG MUNICIPAL BOARD STANDING ORDERS BY LAWS 2014","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
