  FT["BN-S-20-1985-SECTION-4-OF-THE-EMERGENCY-BRUNEI-INVESTMEN-A91C7B"] = {"id":"BN-S-20-1985-SECTION-4-OF-THE-EMERGENCY-BRUNEI-INVESTMEN-A91C7B","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"紧急文莱投资机构修正命令 1985 第 4 条","en":"SECTION 4 OF THE EMERGENCY BRUNEI INVESTMENT AGENCY AMENDMENT ORDER 1985","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-20-1985-SECTION-4-OF-THE-EMERGENCY-BRUNEI-INVESTMENT-AGENCY-AMENDMENT-ORDER-1985.pdf》（2 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-20-1985-SECTION-4-OF-THE-EMERGENCY-BRUNEI-INVESTMENT-AGENCY-AMENDMENT-ORDER-1985.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-20-1985-SECTION-4-OF-THE-EMERGENCY-BRUNEI-INVESTMEN-A91C7B-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"AgencyJ(Amendment), Order 1985 and shall be deemed to have come commence­"},"text":{"en":"Paragraph (2) of Article 7 of the Constitution (Financial Procedure) Amendment of Order, 1959 is amended by deleting the word \"State\" wherever it ap-Article 7(2). pears and substituting therefor \"Government\"."}},{"id":"BN-S-20-1985-SECTION-4-OF-THE-EMERGENCY-BRUNEI-INVESTMEN-A91C7B-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"The Emergency (Brunei Investment Agency) Order, 1984 Amendment of"},"text":{"en":"Paragraph (3) of Article 7 of the Constitution (Financial Procedure) Amendment of Order, 1959 is deleted and the following substituted therefor -Article 7(3). \"3. Moneys standing to the credit of the Government with any bank or otherwise held by the Government may on the order of\n\nNEGARA BRUNEI DARUSSALAM GOVERNMENT GAZETTE His Majesty the Sultan and Yang Di-Pertuan be paid to the Brunei Investment Agency and may be invested by the Brunei In­ vestment Agency -\n\n(a) 8n deposit in any bank; or\n\n(b) in any fund maintained by the Brunei Investment Agency for such investment; or\n\n(c) as otherwise authorised by any written law; and such investments together with any interest received therefrom shall form part of the General Reserve Fund of the Brunei Investment Agency and any part thereof may from time to time be paid by the Brunei Investment Agency to the Con­ solidated Fund.\" Amendment of 3. Paragraph (4) of Article 7 of the Constitution (Financial Procedure) Article 7(4). Order, 1959 is amended by deleting the words \"Consolidated Revenue Account\" and substituting therefor \"General Reserve Fund of the Brunei Investment Agency\". Amendment of 4. Article 14(e) of the Constitution (Financial Procedure) Order, 1959 Article 14(e). is amended(a) by deleting the word \"State\" and substituting therefor \"Government\" ;\n\n(b) by inserting after the words \"the assets and liabilities of the Government\" the words \"other than the assets and liabilities of the Brunei Investment Agency\". Made this 13th day of November, 1985 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nHIS MAJESTY THE SULTAN AND\n\nYANG DI-PERTUAN"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"SECTION 4 OF THE EMERGENCY BRUNEI INVESTMENT AGENCY AMENDMENT ORDER 1985","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-686CA1"] = {"id":"BN-S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-686CA1","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":3,"structureMode":"SECTION","title":{"zh":"宪法职能转移与相应条款命令 1990","en":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS ORDER 1990","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONSEQUENTIAL-PROVISIONS-ORDER-1990.pdf》（2 页），本次切分 3 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONSEQUENTIAL-PROVISIONS-ORDER-1990.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-686CA1-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Constitution (Transfer of Functions Citation. and Consequential Provisions) Order, 1990."}},{"id":"BN-S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-686CA1-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In this Order unless the context otherwise requires -Interpretation. \"functions\" includes any powers, duties, privileges or benefits conferred or imposed by any written law on any person or authority. \"Minister\" means the person appointed under subsection {4) or\n\n(9) of Section 4 of the Constitution who is for the time being charged with the responsibility for the subject matter to which the written law specified in the Schedule refers."}},{"id":"BN-S-20-1990-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-686CA1-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The functions conferred or imposed on the person or authority Transfer of specified in the first column of the Schedule by the provisions of law functions. specified opposite thereto in the second column of that Schedule are hereby transferred to the person or authority specified opposite thereto in the third column of that Schedule.\n\nSCHEDULE (Article 3)\n\nTRANSFER OF STATUTORY FUNCTIONS First Column Second Column Third Column Person or authority Provisions of Law Person or authority from whom func-concerned to whom functions tions transferred transferred PAWNBROKERS ACT (CHAPTER 63) His Majesty The Section 4(3), (4) and Minister Sultan and Yang (5) Di-Pertuan in Council.\n\nBRUNEI DARUSSALAM GOVERNMENT GAZETTE SCHEDULE (Cont'd) First Column Second Column Third Column Person or authority Provisions of Law Person or authority from whom func-concerned to whom functions tions transferred transferred PAWNBROKERS ACT (CHAPTER 63) Minister Section 14( 1) and (2) Minister or such other officer as is authorised by him in that behalf by writing Minister Section 15 Minister or such other officer as is authorised by him in that behalf by writing His Majesty The Section 27 Minister with the Sultan and Yang approval of His Di-Pertuan in Majesty The Sultan Council and Yang Di-Pertuan Made this 28th day of June, 1990 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nHIS MAJESTY\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM Dicetak oleh ALI BIN HAJI HASSAN, Pengarah Percetakan, di Jabatan Percetakan Kerajaan, Kementerian Undang-Undang, Negara Brunei Darussalam. Harga B$5.00"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS ORDER 1990","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007"] = {"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":17,"structureMode":"SECTION","title":{"zh":"海运船员居所条例 2007","en":"MERCHANT SHIPPING CREW ACCOMODATION REGNS 2007","orig":null},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007.pdf》（20 页），本次切分 17 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Merchant Shipping (Crew Accommodation) Regulations, 2007. Interpretation."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these Regulations, unless the context otherwise requires - \"approved\" means approved by the Director or by an authorised organisation; \"authorised organisation\" means an organisation authorised by the Minister under section 125 for the survey or inspection of Brunei Darussalam ships and the issue of any certificate under Part VII of the Order; \"crew accommodation\" includes such sleeping rooms, mess rooms, sanitary accommodation, hospital accommodation and recreation accommodation as are provided for the use of the crew; \"existing ship\" means a ship which is not a new ship; \"new ship\" means a ship of which the keel is laid, or which is at a similar stage of construction, on or after the date of commencement of these Regulations; \"officer\" means a person other than a master designated as such by the crew agreement made under section 57; \"petty officer\" means a rating serving in a supervisory position or a position of special responsibility who is designated as such by the crew agreement made under section 57; \"rating\" means a member of the crew other than the master or an officer; \"ship\" means a ship to which these Regulations apply; \"special limit voyage\" means a voyage within the following limits - from a point 04°35' North, 114°05' East, thence to the point 04°45' North, 114°04' East, thence to the point 04°48' North, 113°55' East, thence due North to latitude 05°02' North, thence due East to longitude 114° 13' East, thence to the point 05°22' North, 114°44' East, thence to . the point 05°07' North, 115°06' East, thence to the point 05°06' North, 115°15' East, thence to the point 04°54' North, 115°06' East and thence following the coast westwards to the starting point; \"surveyor of ships\" means a person appointed as a surveyor of ships under section 5; \"tons\" means gross tonnage measured in accordance with the Merchant Shipping [Tonnage) Regulations, 2006 (S 61/06); \"tug\" means a ship constructed or adapted primarily to engage in towing or similar pursuits. Application and exemption."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(1) Unless otherwise expressly provided, these Regulations(a) shall apply to all new ships, subject to paragraph (c);\n\n(b) shall not apply to any existing ship, subject to paragraph (c), unless(i) the owner of the ship so requests; or liil the crew accommodation in such ship is substantially altered or reconstructed and such alteration or reconstruction takes place on or after the date of commencement of these Regulations;\n\n(c) shall not apply to - (iJ ships of less than 500 tons;\n\n(ii) ships primarily propelled by sail but having auxiliary engines;\n\n(iii) ships engaged in fishing or in similar pursuits;\n\n(iv) tugs; or\n\n(v) ships exclusively engaged on special limit voyages.\n\n(2) These Regulations shall be applied where reasonable and practicable to {a} ships between 200 and 500 tons; and\n\n(b) ships engaged in whaling or in similar pursuits.\n\n(3) The Director may exempt any ship from any of these Regulations either unconditionally or subject to such conditions as he thinks fit if he is satisfied that compliance with that regulation is either impracticable or unreasonable in respect of that ship.\n\nPLANNING AND CONTROL OF CREW ACCOMMODATION Plans."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"PART II"},"text":{"en":"(1) Subject to sub-regulation (3), before the construction of a ship is begun, a plan of the ship, showing the location and general arrangement of the crew accommodation, shall be submitted to the Director or an authorised organisation for approval.\n\n(2) Subject to sub-regulation (3), before - {a} the construction of the crew accommodation in a new ship is begun; or\n\n(b) the crew accommodation in an existing ship is substantially altered or reconstructed, detailed plans of, and information concerning, the accommodation, showing the allocation of each space, the disposition of furniture and fittings, the means and arrangement of ventilation, lighting and heating and the sanitary arrangements, shall be submitted to the Director or an authorised organisation for approval.\n\n(3) Where{a) permission is granted by the Director or an authorised organisation; or\n\n(b) an alteration or reconstruction of the crew accommodation in a ship is temporary or is being carried out as a consequence of an emergency or an accident, the plans referred to in sub-regulations ( 1) and (2) may be submitted to the Director or an authorised organisation as soon as practicable. Surveys and certificates."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"PART II"},"text":{"en":"(1) The survey of ships, so far as regards the enforcement of these Regulations, shall be carried out by a surveyor of ships or an authorised organisation.\n\n(2) A ship shall be surveyed on every occasion when {a) it is registered; {b) its crew accommodation has been substantially altered or reconstructed; or {c) the Director has reason to believe that its crew accommodation does not comply with these Regulations.\n\n(3) After a survey under sub-regulation (2), a ship which complies with these Regulations shall be issued with a crew accommodation certificate by the Director or an authorised organisation.\n\n(4) The crew accommodation certificate issued under sub-regulation (3) shall be in Form 1 set out in the Schedule. ( 5) When a ship is exempted from any of these Regulations under regulation 3, an exemption certificate for crew accommodation in respect of the ship shall be issued by the Director or an authorised organisation.\n\n(6) The exemption certificate for crew accommodation issued under sub-regulation (5) shall be in Form 2 set out in the Schedule.\n\n(7) The certificates issued under sub-regulations (3) and (5) shall be posted up in a prominent and accessible place in the ship.\n\nCREW ACCOMMODATION REQUIREMENTS General."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART III"},"text":{"en":"(1) The location, means of access, structure and arrangement in relation to other spaces of crew accommodation shall be such as to ensure adequate security, protection against weather and sea, and insulation from heat or cold, or undue noise or effluvia from other spaces.\n\n(2) There shall be no direct openings into sleeping rooms from spaces for cargo and machinery or from galleys, lamp and paint rooms, or from engine, deck and other bulk storerooms, drying rooms, communal wash places or water closets. That part of the bulkhead separating such places from sleeping rooms and external bulkheads shall be efficiently constructed of steel or other approved material and shall be watertight and gastight.\n\n(3) External bulkheads of sleeping rooms and mess rooms shall be adequately insulated. All machinery casings and all boundary bulkheads of galleys and other spaces in which heat is produced shall be adequately insulated where there is a possibility of resulting heat effects in adjoining accommodation or passageways. Care shall also be taken to provide protection from heat effects of steam or hot water service pipes.\n\n(4) Internal bulkheads shall be of approved material which is not likely to harbour vermin.\n\n(5) Sleeping rooms, mess rooms, recreation rooms and alley-ways in the crew accommodation space shall be adequately insulated to prevent condensation or overheating.\n\n(6) Main steam and exhaust pipes for winches and similar gear shall not pass through crew accommodation nor, whenever technically possible, through alley-ways leading to crew accommodation; where they do pass through such alley-ways they shall be adequately insulated and encased.\n\n(7) Inside panelling or sheeting shall be of material with a surface easily kept clean. Tongued and grooved boarding or any other form of construction likely to harbour vermin shall not be used.\n\n(8) The construction of the accommodation shall comply with the relevant provisions of the Merchant Shipping (Safety Convention) Regulations, 2003 (S 57/03) as regards the fire-prevention or fire-retarding measures.\n\n(9) The wall surface and deckheads in sleeping rooms and mess rooms shall be made of a material with a surface easily kept clean and, if painted, shall be light in colour. Lime wash must not be used.\n\n(10) The wall surfaces shall be renewed or restored as necessary. ( 11) The decks in all crew accommodation shall be of approved material and construction and shall provide a surface impervious to damp and easily kept clean.\n\n(12) Where the floorings are of composition, the joinings with sides shall be rounded to avoid crevices.\n\n(13) Sufficient drainage shall be provided. Ventilation."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"PART III"},"text":{"en":"( 1) Crew accommodation shall be adequately ventilated.\n\n(2) The system of ventilation shall be controlled so as to maintain the air in a satisfactory condition and to ensure a sufficiency of air movement in all conditions of weather and climate.\n\n(3) Ships regularly engaged on voyages in the tropics and the Persian Gulf shall be equipped with both mechanical means of ventilation and electric fans, except that one only of these means need be adopted in spaces where this ensures satisfactory ventilation.\n\n(4) Except for those ships normally employed in the cold waters of the northern or southern hemispheres, ships engaged outside the tropics shall be equipped with either mechanical means of ventilation or electric fans.\n\n(5) Power for the operation of the aids to the ventilation required by subregulations (3) and (4) shall, when practicable, be available at all times when the crew is living or working on board and when conditions so require. Heating system."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"PART III"},"text":{"en":"(1) An adequate system of heating the crew accommodation shall be provided except in ships engaged exclusively in voyages in the tropics or the Persian Gulf.\n\n(2) The heating system shall, when practicable, be in operation at all times when the crew is living or working on board and when conditions require its use.\n\n(3) In any ship in which a heating system is required, the heating shall be by means of steam, hot water, warm air or electricity.\n\n(4) In any ship in which heating is provided by a stove, measures shall be taken to ensure that the stove is of sufficient size and is properly installed and guarded and that the air is not fouled. j5) The heating system shall be capable of maintaining the temperature in crew accommodation at a satisfactory level under normal conditions of weather and climate likely to be met with on service. Heat load calculations shall be submitted to the Director or an authorised organisation for approval to show that the heating system is capable of ensuring that the temperature in crew accommodation can be maintained at 21 oC when the ventilation system provided for those rooms is working so as to supply at least 25m3 of fresh air per hour for each person for whom that room is designed and when the ambient temperature is -1°C. [6) Radiators and other heating apparatus shall be so placed and, where necessary, shielded as to avoid risk of fire or danger or discomfort to the occupants. Lighting arrangements."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"PART III"},"text":{"en":"( 1) Subject to such special arrangements as may be permitted by the Director in passenger ships, sleeping rooms and mess rooms shall be properly lighted by natural light and shall be provided with adequate artificial light.\n\n(2) All crew spaces shall be adequately lighted. The minimum standard for natural lighting in living rooms shall be such as to permit a person with a normal vision to read on a clear day an ordinary newspaper in any part of the space available for free movement. When it is not possible to provide adequate natural lighting, artificial lighting of the above minimum standard shall be provided.\n\n(3) In all ships, electric lights shall be provided in the crew accommodation. If there are no 2 independent sources of electricity for lighting, additional lighting shall be provided by properly constructed lamps or lighting apparatus for emergency use.\n\n(4) Artificial lighting shall be so disposed as to give the maximum benefit to the occupants of the room.\n\n(5) In sleeping rooms, an electric reading lamp shall be installed at the head of each berth. Sleeping rooms."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"PART III"},"text":{"en":"(1) Sleeping rooms shall be situated above load line amidships or aft.\n\n(2) In exceptional cases, the Director may, if the size, type or intended service of the ship render any other location unreasonable or impracticable, permit the location of sleeping rooms in the fore part of the ship, but in no case forward of the collision bulkhead.\n\n(3) In passenger ships, the Director may, on condition that satisfactory arrangements are made for lighting and ventilation, permit the location of sleeping rooms below the load line, but in no case immediately beneath working alley-ways.\n\n(4) The floor area per person of sleeping rooms intended for ratings shall be not less than - (a} 1.8Sm2 in ships of less than 800 tons;\n\n(b) 2.35m2 in ships of 800 tons or more, but less than 3,000 tons; and\n\n(c) 2. 78m2 in ships of 3,000 tons or more, except that, in the case of passenger ships in which more than 4 ratings are berthed in one room, the minimum floor area per person may be 2.22m2•\n\n(5) In the case of ships in which are employed such groups of ratings as necessitate the employment of a substantially larger number of ratings than would otherwise be employed, the Director may, in respect of such groups, reduce the minimum floor area of sleeping rooms per person, subject to the conditions that\n\n(a) the total sleeping space allotted to the group or groups is not less than would have been allotted had the numbers not been so increased; and (b} the minimum floor area of sleeping rooms is not less than[i) 1.67m2 per person in ships of less than 3,000 tons; and\n\n(ii) 1.85m2 per person in ships of 3,000 tons or more.\n\n(6) Space occupied by berths and lockers, chests of drawers and seats shall be included in the measurement of the floor area. Small or irregularly shaped spaces which do not add effectively to the space available for free movement and cannot be used for installing furniture shall be excluded.\n\n(7) The clear head room in crew sleeping rooms shall not be less than 1.90m.\n\n(8) Except in ships of less than 800 tons, there shall be a sufficient number of sleeping rooms to provide a separate room or rooms for each department.\n\n(9) The number of persons allowed to occupy sleeping rooms shall not exceed the following maxima '\n\n(a) officers in charge of a department, navigating and engineer officers in charge of a watch and senior radio officers or operators -one person per room;\n\n(b) other officers one person per room wherever possible, and in no case more than 2;\n\n(c) petty officers one or 2 persons per room, and in no case more than 2;\n\n(d) other ratings -2 or 3 persons per room wherever possible, and in no case more than 4.\n\n(10) With a view to ensuring adequate and more comfortable accommodation, the Director may grant permission to accommodate up to 10 ratings per sleeping room in the case of certain passenger ships.\n\n(11) The maximum number of persons to be accommodated in any sleeping room shall be indelibly and legibly marked in some place in the room where it can conveniently be seen.\n\n(12) Members of the crew shall be provided with individual berths.\n\n(13) Berths shall not be placed side by side in such a way that access to one berth can be obtained only over another.\n\n(14) Berths shall not be arranged in tiers of more than 2. In the case of berths placed along the ship's side, there shall be only a single tier where a sidelight is situated above a berth.\n\n(15) The lower berth in a double tier shall be not less than 30cm above the floor. The upper berth shall be placed approximately midway between the bottom of the lower berth and the lower side of the deckhead beams.\n\n(16) The minimum inside dimensions of a berth shall be 1.90m by 0.68m. ( 17) The framework and the lee-board, if any, of a berth shall be of approved material, hard, smooth and not likely to corrode to harbour vermin. ( 18) If tubular frames are used for the construction of berths, they shall be completely sealed and without perforations which give access to vermin. [19) Each berth shall be fitted with a spring bottom or a spring mattress and with a mattress of approved material. Stuffing of straw or other material likely to harbour vermin shall not be used. [20) When one berth is placed over another, a dust-proof bottom of wood, canvas or other approved material shall be fitted beneath the spring bottom of the upper berth.\n\n(21) Sleeping rooms shall be so planned and equipped as to ensure reasonable comfort for the occupants and to facilitate tidiness.\n\n(22) The furniture shall include a clothes locker for each occupant. The clothes locker shall be not less than 1.52m in height and of a cross-section area of 0.193m2 and shall be fitted with a shelf and a locking means.\n\n(23) Each sleeping room shall be provided with a table or desk, which may be of the fixed, dropleaf or slide-out type, and with comfortable seating accommodation as necessary.\n\n(24) The furniture shall be of smooth, hard material not liable to warp or corrode.\n\n(25) The drawer or equivalent space for each occupant shall be not less than 0.056m3.\n\n(26) Sleeping rooms shall be fitted with curtains for the side-lights.\n\n(27) Sleeping rooms shall be fitted with a mirror, small cabinets for toilet requisites a book rack and a sufficient number of coat hooks.\n\n(28) As far as practicable, berthing of crew members shall be so arranged that watches are separated and that no day men share a room with watchkeepers. Mess room."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"PART III"},"text":{"en":"(1) Adequate mess room accommodation shall be provided in all ships either by the provision of separate mess rooms for each group of the crew or a single combined mess room for all members of the crew.\n\n(2) The dimensions and equipment of each mess room shall be sufficient for the number of persons likely to use it at any one time.\n\n(3) Mess rooms shall be equipped with tables and seats of an approved type, sufficient for the number of persons likely to use them at any one time.\n\n(4) The Director may permit such exceptions to this regulation concerning mess room accommodation as may be necessary to meet the special conditions in passenger ships.\n\n(5) Mess rooms shall be located apart from the sleeping rooms and as close as practicable to the galley.\n\n(6) Where available pantries are not accessible to mess rooms, adequate lockers for mess utensils and proper facilities for washing utensils shall be provided.\n\n(7) The tops of tables and seats shall be of damp-resisting material, without cracks and capable of being easily cleaned. Recreation room."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"PART III"},"text":{"en":"(1) In all ships, a space or spaces to which the crew can have access when off duty shall be provided on an open deck. The space or spaces shall be of adequate area, having regard to the size of the ship and the crew.\n\n(2) Recreation accommodation, conveniently situated and appropriately furnished, shall be provided for officers and for ratings. Where this is not provided separately from the mess rooms, the latter shall be planned, furnished and equipped to give recreational facilities. Sanitary arrangements."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"PART III"},"text":{"en":"(1) Sufficient sanitary accommodation, including wash basins and tubs or shower baths, shall be provided in all ships.\n\n(2) The following minimum number of separate water closets shall be provided {a) in ships of less than 800 tons 3· I {b) in ships of 800 tons or more, but less than 3,000 tons -4; {c) in ships of 3,000 tons or more -6; {d) in ships where the radio officers or operators are accommodated in an isolated position, sanitary facilities near or adjacent thereto shall be provided.\n\n(3) Subject to sub-regulation (4), the sanitary accommodation provided shall consist of separate sanitary accommodation for males and females if females · are working or living on board.\n\n(4) Sanitary facilities for all members of the crew who do not occupy rooms to which private facilities are attached shall be provided on the following scale{a) one tub or shower bath for every 8 persons or less; {b) one water closet for every 8 persons or less; {c) one wash basin for every 6 persons or less, except that when the number of persons exceeds an even multiple of the specified number by less than one-half of the specified number, this surplus may be ignored for the purpose of this sub-regulation.\n\n(5) When the total number of the crew exceeds 100 and in passenger ships normally engaged on voyages of not more than 4 hours' duration, consideration may be given by the Director to special arrangements or a reduction in the number of facilities required.\n\n(6) Cold fresh water and hot fresh water or means of heating water shall be available in all communal wash places - {a) the crew shall be provided with -\n\n(i) fresh water of capacity sufficient to provide at least 72 litres per man per day and drinking water of capacity sufficient to provide at least 18litres per man per day; or\n\n(ii) drinkable water of capacity sufficient to provide at least 90 litres per man per day if the fresh water provided under sub-paragraph (i) is also of drinkable quality; {b) the number of days shall be sufficient to cover the longest voyage the ship is expected to undertake with a maximum of 30 days; {c) if a distilling or evaporating plant capable of producing (il at least 144 litres of fresh water per man per day and at least 36 litres of drinking water per man per day; or\n\n(ii) at least 180 litres of drinkable water per man per day, is provided, the water capacity to be provided for the crew may be reduced to at least 7 days' supply, or sufficient to cover the longest voyage the ship is expected to undertake, whichever is the less, subject to paragraph fa).\n\n(7) Wash basins and tub baths shall be of adequate size and constructed of approved material with a smooth surface not liable to crack, flake or corrode.\n\n(8) All water closets shall have ventilation to the open air, independently of any other part of the accommodation.\n\n(9) All water closets shall be of a pattern approved by the Director or an authorised organisation and shall be provided with an ample flush of water, available at all times and independently controllable.\n\n(10) Soil pipes and waste pipes shall be of adequate dimensions and shall be so constructed as to minimise the risk of obstruction and to facilitate cleaning.\n\n(11) Sanitary accommodation intended for the use of more than one person shall comply with the following requirements fa) floors shall be of approved durable material, easily cleaned and impervious to damp, and shall be properly drained; {b) bulkheads shall be of steel or other approved material and shall be watertight up to at least 23cm above the level of the deck; {c) the accommodation shall be sufficiently lighted, heated and ventilated;\n\n(d) water closets shall be situated convenient to, but separate from, sleeping rooms and wash rooms, without direct access from the sleeping rooms or from a passage between sleeping rooms and water closets to which there is no other access, except that this requirement shall not apply where a water closet is located in a compartment between 2 sleeping rooms having a total of not more than 4 persons; (eJ where there is more than one water closet in a compartment, it shall be sufficiently screened to ensure privacy. ( 12) In all ships, facilities for washing and drying clothes shall be provided on a scale appropriate to the size of the crew and the normal duration of the voyage.\n\n(13) The facilities for washing clothes shall include suitable sinks, which may be installed in wash rooms, if separate laundry accommodation is not reasonably practicable, with an adequate supply of cold fresh water and hot fresh water or means of heating water.\n\n(14) The facilities for drying clothes shall be provided in a compartment separate from sleeping rooms and mess rooms, adequately ventilated and heated and equipped with lines or other fittings for hanging clothes. Hospital accommodation."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"PART III"},"text":{"en":"(1) In any ship carrying a crew of 15 or more and engaged in a voyage of more than 3 days' duration, separate hospital accommodation shall be provided. The Director may relax this requirement in respect of ships engaged in coastal trade.\n\n(2) The hospital accommodation shall be suitably situated, so that - (aJ it is easily accessible; and (bJ the occupants may be comfortably housed and may receive proper attention in all weathers.\n\n(3) The arrangement of the entrance, berths, lighting, ventilation, heating and water supply shall be designed to ensure the comfort, and to facilitate the treatment, of the occupants.\n\n(4) Hospitals shall be provided with one berth for every 50 or fraction of 50 members of the crew, and one berth for every additional 12 crew members or fraction thereof, above 50. [5) Water closet accommodation shall be provided for the exclusive use of the occupants of the hospital accommodation, either as part of the accommodation or in close proximity thereto.\n\n(6) Hospital accommodation shall not be used for any purpose other than medical purposes.\n\n(7) An approved medicine chest with readily understandable instructions shall be carried in every ship which does not carry a doctor. Other arrangements."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"PART III"},"text":{"en":"(1) Sufficiently and adequately ventilated accommodation for the hanging of oil skins shall be provided outside, but convenient to, the sleeping rooms.\n\n(2) In ships regularly engaged on voyages to mosquito-infested ports, provision shall be made to protect the crews~ quarters against the admission of mosquitoes by the fitting of suitable screens to sidescuttles, ventilators and doors to the open deck. National habits and customs."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"PART III"},"text":{"en":"(1) In the case of the ships mentioned in sub-regulation (5) of regulation 10, the Director may, in respect of the members of the crew thereof, modify the requirements laid down in the foregoing regulations as far as may be necessary to take account of their distinctive national habits and customs and in particular may make special arrangements concerning the number of persons occupying sleeping rooms and concerning mess room and sanitary facilities.\n\n(2) Where special arrangements are made under sub-regulation ( 1), the modified requirements shall be subject to the specifications set out in sub-regulations (1) and (2) of regulation 10 and by the minimum sleeping space requirements prescribed for such groups of ratings in sub-regulation (5) of regulation 10.\n\n(3) In the case of the ships referred to in sub-regulation (5) of regulation 10, the hospital, dining, bathing and sanitary facilities shall be provided and maintained on a standard, in regard to their quantity and practical usefulness, -equal or comparable to that which obtains aboard all other ships of similar type. Maintenance of crew accommodation."}},{"id":"BN-S-20-2007-MERCHANT-SHIPPING-CREW-ACCOMODATION-REGNS-2007-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"PART III"},"text":{"en":"( 1) Crew accommodation shall be maintained in a clean and decently habitable condition and shall be kept free of goods and stores that are not the personal property of the occupants.\n\n(2) The master, or an officer specially deputed for the purpose by him, accompanied by one or more members of the crew, shall inspect all crew accommodation at intervals of not more than one week. The results of each such inspection shall be recorded in the official log-book.\n\nSCHEDULE FORM 1 regulation 5(4)\n\nCREW ACCOMMODATION CERTIFICATE (This Certificate shall be supplemented by a Record of Crew Accommodation)\n\nBRUNEI DARUSSALAM Issued under the provisions of the Merchant Shipping (Crew Accommodation) Regulations, 2007 Official Number IMO Port of Gross Name of Ship or Number Registry Tonnage Date Keel Laid • Call Sign Type of Ship: ________ _ Crew on Board: Master: _______ persons Officers: persons Petty Officers: persons Ratings: persons Total: persons THIS IS TO CERTIFY: That the ship has been surveyed in accordance with regulation 5 of the Merchant Shipping (Crew Accommodation) Regulations, 2007 and that the crew accommodation of the ship complied with the provisions of the Regulations. Issued at _______ on the ____ day of _____ 20_. (Name and signature of duly authorised official issuing the certificate) (Seal or stamp of the issuing Authority, as appropriate) • It will be sufficient to indicate the year in which the keel was laid or when the ship was at a similar stage of construction except for {INSERT YEAR IN FORCE}, in which case the actual date should be given. FORM2 regulation 5(6)\n\nEXEMPTION CERTIFICATE FOR CREW ACCOMMODATION\n\nBRUNEI DARUSSALAM Issued under the provisions of the Merchant Shipping (Crew Accommodation} Regulations, 2007 Official Number IMO Port of Gross Name of Ship or Number Registry Tonnage Date Keel Laid • ! 1 Call Sign I I THIS IS TO CERTIFY: That the ship is, under the authority conferred by regulation 3 of the Merchant Shipping (Crew Accommodation) Regulations, 2007 exempted from the requirement of of the Regulations subject to the following conditions: and limited to the following voyages: Issued at _______ on the ____ day of _____ 20_. (Name and signature of duly authorised official issuing the certificate} (Seal or stamp of the issuing Authority, as appropriate) It will be sufficient to indicate the year in which the keel was laid or when the ship was at a similar stage of construction except for {INSERT YEAR IN FORCE}, in which case the actual date should be given. Made this 21st. day of Rabiulawal, 1428 Hijriah corresponding to the 9th. day of April, 2007.\n\nPEHIN ORANG KAYA SERI KERNA DATO SERI\n\nSETIA HAJI AWANG ABU BAKAR BIN HAJI APONG Minister of Communications, Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"MERCHANT SHIPPING CREW ACCOMODATION REGNS 2007","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001"] = {"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":25,"structureMode":"SECTION","title":{"zh":"药剂师注册命令 2001","en":"PHARMACISTS REGISTRATION ORDER 2001","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001.pdf》（12 页），本次切分 25 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"11) This Order may be cited as the Pharmacists Registration Order 2001 and shall commence on a date to be appointed by the Minister with the approval of His 1 Majesty the Sultan and Yang Di-Pertuan by notification in the Gazette.\n\n(2) The long title of this Order is \"An Order to provide for the registration of and for purposes connected therewith\"."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In this Order/ unless the context otherwise requires - \"annual certificate\" means the certificate referred to in subsection 11) of 15; \"Board\" means the Pharmacy Board established under section 3; the person appointed as Chairman of the Board; \"Minister\" means the Minister of Health; \"register\" means the register of pharmacists maintained in pursuance of 6; \"registered pharmacist\" means a person whose name has been registered in \"Registrar\" means the Registrar of Pharmacists referred to in section 5. Establishment and constitution of Board."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(1) For the purposes of this Order, there is hereby established a Pharmacy Board which shall consist of -\n\n(a) the Director of Pharmaceutical Services ex officio, who shall be the\n\n(b) not less than 4 other members to be appointed by the Minister, being persons eligible to apply for registration under this Order, at least one of whom shall be in private service.\n\n(2) The period of appointment of members, other than the Chairman, shall be 3 years, but such members shall be eligible for re-appointment.\n\n(3) Notwithstanding subsection (2), the Minister may, at any time, in his discretion, suspend or terminate the appointment of any member of the Board, than the Chairman, and may appoint another person in his place or in the place of any member who retires, dies, vacates his office, or who, for the time being, is unable to act or who is absent from 3 consecutive meetings of the Board without such excuse as may seem reasonable to the Minister; and every person so appointed shall hold office for the residue of the term for which his predecessor was appointed.\n\n(4) All acts done by the Board shall, notwithstanding any vacancy in the or that it is afterwards discovered that there was a defect in the appointment of any person purporting to be a member thereof, be valid as if no such vacancy or had existed. of Board. ,•"}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"( 1) In the absence of the Chairman from any meeting of the Board, the members present shall elect from amongst themselves a person to be the chairman for that meeting. {2) The chairman of a meeting shall have an original vote and also a casting vote. {3) The Board shall meet at such places and times as the Chairman may and at a meeting 3 members shall form a quorum.\n\n(4) No business shall be transacted at a meeting unless a quorum is present. {5) Subject to the provisions of this Order, the Board may determine its own procedure. 14th. 2001\n\n(6) The Board shall cause proper records of its proceedings to be kept. of Pharmacists."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Director of Pharmaceutical Services shall be the Registrar of who shall be responsible for the maintenance and custody of the and the performance of such other duties in connection therewith as may be necessary. of pharmacists."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"For the purposes of this Order, a register of pharmacists shall be in such form as the Board may determine and shall contain the names and addresses, and such other particulars, if any, as the Board may determine, of all persons who are registered therein. .~ eligible for registration."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Subject to this Order, the following persons shall be entitled to be registered Order - fa) any person employed as a pharmacist by the Government at the date of commencement of this Order;\n\n(b) any other person who holds any qualification granted in respect of\n\n(i) which is recognised as entitling him to register with the Royal Pharmaceutical Society of Great Britain or who is the holder of such other qualification in pharmacy as the Board may declare, by in the Gazette, to be an approved qualification for the purpose of this section;\n\n(ii) who has complied with such conditions as the Board may\n\n(iii) who has satisfied the Board at an examination in forensic pharmacy that he is eligible to be registered under this Order. for registration."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"( 1) Any person eligible for registration under this Order may apply to the Board for registration. Every such application shall be made in such form and manner and accompanied by such documents, photographs and particulars, as the Board may determine.\n\n(2) When such person has complied with the requirements of subsection (1) and has paid the fee as prescribed in the Schedule, the Chairman shall, subject to\n\n(2) of section 9, enter his name in the register.\n\n(3) The Board may refuse to enter in the register the name of any person who, in the opinion of the Boardfa) is not of good character and reputation; or {b) is unable to carry out the duties of a pharmacist effectively in Brunei Darussalam.\n\n(4) No person shall be registered unless he has attained the age of 21 years. of certificates of registration."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"( 1) Where a person has had his name entered in the register pursuant to\n\n(2) of section 8, the Board shall issue to him a certificate of registration in such form as it may determine.\n\n(2) Where a person has had his name entered in the register subject to any and conditions, such restrictions and conditions shall be endorsed on his certificate of registration and the certificate so endorsed shall have effect subject to such restrictions and conditions.\n\n(3) the year in which the certificate of registration is issued, that certificate shall be d~emed to be the annual certificate issued under section 15 and the provisions of this Order relating to annual certificates shall apply to it. on use of certain titles."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"(1) No person shall, unless he is registered, take or use the name or title of pharmaceutical chemist, pharmaceutist, druggist, chemist, pharmacist, apothecary or any other word in any language having the same or similar meaning or being to the like intent, or take or use in connection with the sale of goods by retail the name or title of dispensing chemist or any other name, title, emblem or description implying that he or any person employed by him is registered or that he or such other person is entitled to be registered.\n\n(2) A person who acts in contravention of subsection ( 1) is guilty of an and liable on conviction to a fine not exceeding $1,000 and to a further fine of $100 for every day during which the offence continues after conviction. of higher qualifications."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Every person registered under this Order who has obtained any higher pharmaceutical qualification than the qualification in respect of which he has been registered shall be entitled to have such higher qualification inserted in the register in substitution for or in addition to the qualification previously registered, without of any further fee. of register and presumptions."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"(1) The Registrar shall publish in the Gazette, as sopn as practicable after 1st of each year and on such other occasions as he ·may consider necessary, a the names, addresses, qualifications and dates of qualifications of all registered pharmacists.\n\n(2) In any proceedings -\n\n(a) the publication of a list under subsection (ll shall be prima facie that the persons whose names appear therein are registered pharmacists;\n\n(b) an annual certificate issued in pursuance of section 15 shall be as prima facie evidence that the person named therein as a registered pharmacist is a registered pharmacist; and\n\n(c) a certificate under the hand of the Registrar that the name of a has been entered or removed from the register shall be conclusive evidence that the person is or is not registered under this as the case may be. of particulars in register."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Registrar shall insert in the register any change which may come to his in the name, address or other particulars of any registered pharmacist. of name in register."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"jl) Every registered pharmacist who desires to be retained on the register the 30th November of the preceding year and on payment of the fee as prescribed in the Schedule, make application in such form as the Board may determine for such retention.\n\n(2) A registered pharmacist who makes an application and payment pursuant to subsection !1) shall have his name retained in the register.\n\n(3) A person who fails to make an application pursuant to subsection (1) but who subsequently does so and pays the prescribed fee referred to in that and such additional fee, if any, as may be prescribed in the Schedule shall, subject to section 17, be entitled to have his name retained in the register during that year. certificate."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"(1) an application and on payment of the prescribed fee pursuant to section 14, the applicant shall, subject to this Order, be entitled to a certificate certifying that he is registered under this Order. {2) The annual certificate shall be in such form as the Board may determine.\n\n(3) Subject to subsection (4), the annual certificate shall be issued by the and shall be in force from the date of issue to the end of the year.\n\n(4) If the name of a person, to whom an annual certificate has been issued this section, is removed from the register under section 16 or 17, the annual certificate shall cease to be valid. of name from register ."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"(1) The Registrar shall remove from the register the name and other particulars of a registered pharmacist who(a) has died;\n\n(b) has failed to make an application for the retention of his name on the register before the expiry of the year in which the name is -\n\n(i) under subsection (2) of section 8;\n\n(ii) retained in the register under subsection (2) of section 14; or jiii) restored to the register under subsection (1) of section 18; 14th. 2001 {cj has failed to notify the Registrar of a change in his business address or has not supplied to him an address in Brunei Darussalam at he can be found; or {d) has been registered through an error as to his qualification for\n\n(2) For the purposes of paragraph {c) of subsection (1), a person failing to acknowledge within 3 months of the date of despatch, the receipt of a registered letter addressed to him at the last address supplied by him to the Chairman, shall be deemed not to have supplied the Registrar with an address under that of Board to cancel annual certificate and remove name from register."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Ill Subject to this section,.the Board may direct tllat an annual certificate be and the name and other particulars of a registered pharmacist be frolll. the regis~er if - (a} he has been convicted of an offence involving fraud or dishonesty; {b) he has been convicted of an offence under this Order; {c) his registration has been obtained by fraud or misrepresent~tion; · {d)· his quali£icationJor.r~gi;;tratioi1 ullder~ection 7 hasbeenwithdr~wn the authority through\"which it was acquired or by which it was awarded; ; {~) . he has been foiind g\"4ilty ota.n improp~r act or conduct as, ~fter due t}fe Board, rende~$hi~tin ~he opinioq oftpe S~ard, l:J.:rl(lt to be~ pharmaci~t; 9! · · · · .. :: . · - . (f) it:appears to • I ' • • .: he is. ' unable to carry .\\ • • ' > O,l:\\t ' dupet) ,' • «;>£.a '' theJ3~d t}la~ )~.~. .phar.~.:;iste#e.ctiy:elyjn Brunei Par~ssalam. · ~ ;;_.,\" :(21.; ; No··direction.shaU ,be .given under subsection (lf :unles.s •the Boo.r~th~ given the registered pharmacist· to \\f/ltom ·the • direction .relates ,an opportunity. of being heard either personally or by counsel. (3} A direction under subsection .(1) s~alLnot,take.effec::t: until the expiration of one month from the date on which the direction has been communicated to the registered pharmacist to whom the direction relates or, where an appeal against the direction has been made to the Minister under section 19, until the appeal has been determined or withdrawn.\n\nDARUSSALAM GOVERNMENT GAZETTE\n\n(4) Where a direction under subsection (1) takes effect, the Registrar shall make such alteration in the register as is necessary to give effect to the direction."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"(1) Where the name of a person has been removed from the register under (cj of subsection (ll of section 16, the Board shall on receipt of the required information, restore the name to the register upon application in such form as the Board may determine and on payment of the fee as prescribed in the\n\n(2) Where a name removed from the register under paragraph (bj or (cf of\n\n(1) of section 16 has been restored, such restoration shall, if the Board so directs, have effect from the date of the removal of the name. against removal from register or refusal to register."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Any person aggrieved by the removal of his name from the register, or by any refusal or failure to enter his name in the register, or by any refusal to issue to him an annual certificate, or by the cancellation of his annual certificate, may appeal to the Minister whose decision shall be final. and powers of Inspectors."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"11) The Minister may appoint such number of persons to be Inspectors as he may consider necessary for the purposes of this Order.\n\n(2) When an Inspector has reasonable cause to believe that any offence under this Order has been>or is being committed on any premises or in connection with any business carried on in any premises, he may, at all reasonable times, enter upon such premises and may search and examine such premises and may inspect, remove and detain any books, documents or other articles found therein which in the opinion of such Inspector may furnish evidence of the commission of an offence against this Order and may require any person conducting or managing any business of keeping, retailing, dispensing or compounding any poison, any substance or product specified in the First Schedule to the Misuse of Drugs Act (Chapter 27) or any other therapeutic substance to produce for his inspection any certificate issued to such person or his employer under this Order.\n\n(3) Any person who obstructs or impedes an Inspector in the performance of his duties under this Order is guilty of an offence. 14~. ~CFl 1 2001"}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"A registered pharmacist in public office shall be exempted from payment of any fee as prescribed pursuant to this Order. of Schedule."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"The Minister, with the approval of His Majesty the Sultan and Yang Di-Pertuan, may by order published in the Gazette amend the Schedule. registration."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"A person who, in an application for registration under this Order, makes, produces or causes to be made or produced, any false or fraudulent representation, certificate or declaration, either verbally or in writing, and any who knowingly aids or assists therein is guilty of an offence and liable on conviction to a nne not exceeding $1,000, imprisonment for a term not exceeding one year or both."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Any person who contravenes or fails to comply with any provision of this any rule made thereunder for which no special penalty is provided is an offence and liable on conviction to a nne not exceeding $1,000, imprisonment for a term not exceeding one year or both."}},{"id":"BN-S-21-2001-PHARMACISTS-REGISTRATION-ORDER-2001-A25","no":25,"noLabel":{"en":"Section 25."},"heading":{"en":"-Fees"},"text":{"en":"The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, make rules to carry out generally the objects and purposes of this 8, 14 and 18 Fees Registration fee $200 $100 $150 Made this 21st. day of Zulkaedah, 1421 Hijriah corresponding to the 15th. day of February, 2001 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"PHARMACISTS REGISTRATION ORDER 2001","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-21-2006-E-LEGAL-PROFESSION-ACT-AMENDMENT-NO-2-ORDER-2006-1"] = {"id":"BN-S-21-2006-E-LEGAL-PROFESSION-ACT-AMENDMENT-NO-2-ORDER-2006-1","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"法律职业法修正第 2 号命令 2006(1)","en":"LEGAL PROFESSION ACT AMENDMENT NO. 2 ORDER 2006(1)","orig":null},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-21_2006_E-LEGAL-PROFESSION-ACT-AMENDMENT-NO.-2-ORDER-2006(1).pdf》（2 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-21_2006_E-LEGAL-PROFESSION-ACT-AMENDMENT-NO.-2-ORDER-2006(1).pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-21-2006-E-LEGAL-PROFESSION-ACT-AMENDMENT-NO-2-ORDER-2006-1-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Legal Profession Act (Amendment) (No. 2) of section 3 of Chapter 132."}},{"id":"BN-S-21-2006-E-LEGAL-PROFESSION-ACT-AMENDMENT-NO-2-ORDER-2006-1-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"27th. FEBRUARY, 2006"},"text":{"en":"Section 3 of the Legal Profession Act is amended - {a) in subsection (1) -\n\n(i) in paragraph (b), by deleting \"or\" from the last line;\n\n(ii) in paragraph {c), by deleting the fullstop and by substituting \"; or\"\n\n(iii) by adding the following new paragraph - \"(d) is a barrister, solicitor or who is a barrister and solicitor of a Supreme Court of any Australian State or Territory.\";\n\n(b) in subsection (3), by inserting \", in any Australian State or Territory\" immediately after \"Malaysia\" in the eight line. Made this 23rd. day of Muharam, 1427 Hijriah corresponding to the 22nd. day of February, 2006 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI PERTUAN\n\nDARUSSALAM"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"LEGAL PROFESSION ACT AMENDMENT NO. 2 ORDER 2006(1)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035"] = {"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":20,"structureMode":"SECTION","title":{"zh":"海运纪律罪行条例 2007","en":"MERCHANT SHIPPING DISCIPLINARY OFFENCES REGULATIONS 2007","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REGULATIONS-2007.pdf》（10 页），本次切分 20 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REGULATIONS-2007.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Merchant Shipping (Disciplinary Offences) Regulations, 2007. Application."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"These Regulations shall apply to any seaman employed in a Brunei Darussalam ship other than in a ship -\n\n(a) whose ordinary course of navigation does not extend beyond the limits of any port in Brunei Darussalam, if and so long such ship is engaged in the service for which it is intend; or\n\n(b) solely in connection with the construction, alteration, repair or testing of the ship, its machinery or equipment, and not engaged in the navigation of the ship. General disciplinary offences."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is a disciplinary offence on board a Brunei Darussalam ship for a seaman to whom these Regulations apply -\n\n(a) to wilfully strike any person on board the ship;\n\n(b) to wilfully disobey a lawful command;\n\n(c) to use insolent or contemptuous language to the master or any seaman;\n\n(d) without reasonable cause\n\n(i) to fail to be available for duty at a time when he is required by the master, or by a person authorised by the master, to be so available;\n\n(ii) to fail to report or to remain at his place of duty at a time when he is so required to be at that place; or\n\n(iii) while on duty, to be asleep at his place of duty;\n\n(e) to be under the influence of alcohol or a drug, whether alone or in combination, to such an extent that he behaves in a disorderly manner or is unfit to be entrusted with his duty or with any duty which he might be called upon to perform, unless the drug was taken by him for medical purposes and either -\n\n(i) he took it on medical advice and complied with any direction given as part of that advice; or\n\n(ii) he had no reason to believe that the drug might have the influence it had;\n\n(f) without the consent of the master or of any other person authorised to give it, to bring on board the ship or to have in his possession on board any offensive weapon or offensive instrument; or\n\n(g) wilfully and without reasonable cause -\n\n(i) to damage the ship or any property on board the ship; or\n\n(ii) to throw any such property overboard. Disciplinary offences on board certain ships."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"( 1) It is a disciplinary offence on board a Brunei Darussalam ship described in sub-regulation (3) for a seaman to whom these Regulations apply(a) to smoke;\n\n(b) to use a naked light or mechanical lighter; or\n\n(c) to use an electric torch which is not of a type approved by the master, in any part of the ship in which smoking or the use of such a light, mechanical lighter or torch is prohibited by the master or the employer.\n\n(2) It is a disciplinary offence on board a Brunei Darussalam ship described in sub-regulation (3) for a seaman to whom these Regulations apply, without the consent of the master or of any other person authorised to give it, to bring on board the ship or to have in his possession on board any matches or a mechanical lighter. {3} The description of a Brunei Darussalam ship referred to m subregulations (1) and (2) is any Brunei Darussalam ship in which - {a} by reason of the cargo or stores which are or have been carried in the ship, there is a special risk of fire or explosion; and {b) the master or the employer has given notice to seaman in the ship, whether by means of notices displayed in the ship or otherwise, that the act mentioned in sub-regulations {l){a}, {b), {c) or (2), as the case may be, is prohibited, either in all or specified parts of the ship.\n\n(4) In this regulation, \"mechanical lighter\" includes any mechanical, chemical or electrical contrivance designed or adapted for or capable of causing fire or explosion. Disciplinary offences dealt with by master or authorised officer."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"[ 1) A disciplinary offence may be dealt with by the master of the Brunei Darussalam ship on board where the offence is alleged to have occurred and the master may impose a fine, not exceeding such amount as is specified in regulation 8, on the seaman whom he finds has committed the offence. {2} The powers and duties of the master in relation to a disciplinary offence under these Regulations may be exercised or performed by any officer authorised for the purpose by the master, and the name of the officer so authorised shall be entered by the master in the official log-book. Disciplinary offences to be dealt with speedily."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"(1} A disciplinary offence shall be dealt with within 24 hours from the time . it comes to the notice of the master, unless it is not practicable to deal with it within that time, in which case, it shall be dealt with as soon as practicable thereafter. {2) If a disciplinary offence is not dealt with within 24 hours from the time it comes to the notice of the master, the reason for the delay shall be recorded in the official log-book. Procedure for disciplinary offences."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In dealing with a disciplinary offence, the following procedure shall be followed{a) a seaman charged with a disciplinary offence shall, if he so requests, be permitted at the hearing before the master to be accompanied by any person for the purpose of advising him and that person may speak on behalf of the seaman;\n\n(b) the charge shall be entered by the master in the official log-book and shall be read and explained to the seaman by the master, who shall record therein that it has been so read and explained and a copy of the charge shall be given to the seaman; {c) the seaman shall then be asked whether or not he admits the charge and(i) if he admits it, the admission shall be recorded by the master in the official log-book; or\n\n(ii) in all other cases, an entry to the effect that the seaman does not admit the charge shall be recorded therein;\n\n(d) the evidence of any witness called by the master shall be heard in the presence of the seaman, who shall be afforded reasonable opportunity to question the witness on his evidence; {e) the seaman shall be given an opportunity to make a statement in answer to the charge, including any comments on the evidence produced against him and particulars of the statement, or a record that the seaman declined to make one, if such should be the case, shall be entered by the master in the official log-book or contained in a separate document annexed to, and referred to in an entry made by the master in, the official log-book; {f) the seaman shall be permitted to call witnesses to give evidence on his behalf, and any such witness may be questioned by the master on his evidence; {g) the master shall, after consideration of all the evidence given before him, give his decision in the presence of the seaman as to whether he finds the seaman has committed the offence charged and -\n\n(i) if he finds that the seaman has not committed the offence, he shall dismiss the charge; or\n\n(ii) if he finds that the seaman has committed the offence, he shall, after having regard to any mitigating circumstances brought to his notice, give his decision either as to the amount of the fine he is imposing or that he is imposing no fine, and the master shall record his decisions in the official log-book; and {h) the master shall -\n\n(i) inform the seaman on whom a fine has been imposed, of his right of appeal under section 84 and of the time within which notice of intended appeal must be given in accordance with these Regulations; and (ii] if the seaman so requests, supply to him copies of all entries in the official log-book, including any annexes thereto, referring to the disciplinary offence to which the fine relates. Fines imposed for disciplinary offences."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"! 1] The fine that may be imposed on a seaman for a disciplinary offence under regulation 3 shall be an amount not exceeding $50 or, in the case of a second or subsequent commission of the offence before the seaman is discharged from the ship, an amount not exceeding $100.\n\n(2) The fine that may be imposed on a seaman for a disciplinary offence under regulation 4 shall be an amount not exceeding $100. Remission of fines imposed."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A fine imposed on a seaman for a disciplinary offence may be remitted in whole or in part by the master{a) if the master is of the opinion that the seaman's conduct, since the fine was imposed, has been such as to justify the remission; or {b) if new evidence has been discovered which was not known to the master at the time he dealt with the offence and which, in his opinion, justifies the remission, · and a record of every such remission shall be entered in the official log-book by the master. Fine imposed pending appeal."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A fine imposed on a seaman for a disciplinary offence and against which an appeal is pending at the time mentioned in section 86 may be provisionally deducted from the seaman's wages pending the appeal. Place of hearing for appeals."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Subject to regulation 14, an appeal by a seaman against a fine for a disciplinary offence shall be heard by the Director in Brunei Darussalam. Time limit for notice of appeal."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"If a seaman on whom a fine has been imposed for a disciplinary offence wishes to appeal against the decision to the Director, he shall give notice of intended appeal to the master within 2 days of the decision, provided that if the decision is given within 2 days of the ship's expected time of arrival in Brunei Darussalam, the notice shall be given before the ship's arrival. Duties of master in relation to appeals."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Upon receipt of a notice of intended appeal from the seaman, the master shall(aJ make an entry in the official log-book recording the date of receipt of the notice; and (bJ give notice of appeal to the Director not later than 7 days after the receipt of the notice, provided that if it is not practicable to give notice within that period, it shall be given as soon as practicable thereafter and the reason for the delay shall be recorded in the official log-book. Alternate place of hearing for appeals."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"11) Notwithstanding anything contained in regulation 11, if the Director, having regard to all the circumstances of the case, is of the opinion that it is expedient that the appeal shall be heard outside Brunei Darussalam, the appeal shall be heard at such place as the Director may direct and before such person as the Director may appoint.\n\n(2) For the purposes of an appeal heard under this regulation, regulations 15 to 18 shall apply as if any reference to the Director in those regulations includes a reference to the person appointed by the Director under sub-regulation (1). Arrangement for hearing of appeals."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"(1) The Director shall make arrangements as to the place, date and time at which the appeal is to be heard and shall inform the master or employer of those arrangements.\n\n(2) The master or employer shall, upon being informed by the Director of the arrangements which have been made for hearing the appeal, inform the seaman of those arrangements.\n\n(3) The master shall supply to the seaman copies of all entries in the official log-book, including annexes thereto, referring to the disciplinary offence to which the appeal relates, unless he has already supplied those copies in accordance with regulation 7{h)(ii). Furnishing of entries to Director."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The master shall supply the Director with copies of all entries in the official log-book, including any annexes thereto, referring to the disciplinary offence to which the appeal relates and produce to him the official log-book. Procedure relating to appeals."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"[ll In hearing an appeal, the following procedure shall be followed{a) the seaman shall, if he so requests, be permitted at the hearing to be accompanied by any person for the purpose of advising him and that person may speak on behalf of the seaman; {b) the seaman shall be given an opportunity to state the grounds of his appeal, to produce supporting evidence and to call witnesses to give evidence on his behalf; {c) subject to sub-regulation [2), the master shall be given an opportunity to call witnesses and to give evidence himself; {d) the evidence of any witness, whether called by the Director or otherwise, shall be heard in the presence of the seaman; {e) subject to sub-regulation (2), both the seaman and the master shall be afforded reasonable opportunity to question any witness on his evidence and to comment upon it; and {f) the Director shall notify the seaman, and the master or employer, of his decision regarding the appeal and shall record the decision in the official log-book.\n\n(2) If the master is absent from the hearing of the appeal and the Director is satisfied that no injustice will result, the appeal may, notwithstanding sub-regulations (l){c) and {e), be heard and determined by the Director in the absence of the master. Further arrangements for hearing of appeals."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"(1) Where a seaman is not present at the place, date and time arranged for the hearing of his appeal -\n\n(a) if the seaman so requests within one month from that date; and\n\n(b) if the seaman had not been informed of those arrangements or had other reasonable excuse for not being present, the Director shall make further arrangements for the appeal to be heard.\n\n(2) If the Director makes further arrangements for the appeal to be heard, he shall notify the seaman and the employer.\n\n(3) It shall be sufficient compliance with the requirements of subregulation (2) for the notification to be sent by registered post to the last known address of the seaman and to the last known address of the employer. Entries in official log-book."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"All entries in the official log-book, including annexes thereto, required to be made by the master under these Regulations shall be signed by the master and by a member of the crew. Penalties."}},{"id":"BN-S-21-2007-MERCHANT-SHIPPING-DISCIPLINARY-OFFENCES-REG-0E9035-A20","no":20,"noLabel":{"en":"Section 20."},"heading":{"en":"MERCHANT SHIPPING ORDER, 2002"},"text":{"en":"The master, or the officer authorised by him under regulation 5(2) to exercise the powers of the master and to perform his duties in relation to a disciplinary offence, who fails to make an entry in an official log-book required to be made by the master under these Regulations or who fails to comply with an obligation imposed upon him under regulations 7(h)(iJ, 13(b), 15(2) or (3) or regulation 16 shall be guilty of an offence and liable on conviction to a fine not exceeding $500. Made this 21st. day of Rabiulawal, 1428 Hijriah corresponding to the 9th. day of April, 2007.\n\nPEHIN ORANG KAYA SERI KERNA DATO SERI\n\nSETIA HAJI AWANG ABU BAKAR BIN HAJI APONG Minister of Communications, Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"MERCHANT SHIPPING DISCIPLINARY OFFENCES REGULATIONS 2007","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
