  FT["BN-S-22-1985-E-CORRIGENDA-FOR-LAW-REVISION-OMITTED-LAWS-340BBC"] = {"id":"BN-S-22-1985-E-CORRIGENDA-FOR-LAW-REVISION-OMITTED-LAWS-340BBC","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"法律修订遗漏法律第 2 号命令勘误 1985","en":"CORRIGENDA FOR LAW REVISION OMITTED LAWS ORDER No.2 1985","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22_1985_E-CORRIGENDA-FOR-LAW-REVISION-OMITTED-LAWS-ORDER-No.2-1985.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22_1985_E-CORRIGENDA-FOR-LAW-REVISION-OMITTED-LAWS-ORDER-No.2-1985.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-1985-E-CORRIGENDA-FOR-LAW-REVISION-OMITTED-LAWS-340BBC-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"NEGARA BRUNEI DARUSSALAM GOVERNMENT GAZETTE No. S 22 CORRIGENDA In Government Gazette Part II Issue No. 11 dated 17th. October, 1985, in English version on page 120 the sentence, \"Educations (Brunei Board of Examinations)\" should read as \"Education (Brunei Board of Examinations)\" and on page 123 the sentence \"Chronoiogical Table of Acts\" should read as \"Chronological Table of Acts\". Dicetak oleh ALI BIN HAJI HASSAN, Pemangku Pengarah Percetakan, diJabatan Percetakan Kerajaan, Kementerian Undang-Undang, Negara Brunei Darussalam. Harga BSS.OO"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CORRIGENDA FOR LAW REVISION OMITTED LAWS ORDER No.2 1985","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
