  FT["BN-S-22-1998-PROCLAMATION-OF-EMERGENCY"] = {"id":"BN-S-22-1998-PROCLAMATION-OF-EMERGENCY","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"紧急状态宣布","en":"PROCLAMATION OF EMERGENCY","orig":null},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22-1998-PROCLAMATION-OF-EMERGENCY.pdf》（3 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22-1998-PROCLAMATION-OF-EMERGENCY.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-1998-PROCLAMATION-OF-EMERGENCY-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No. S 22\n\nTHE CONSTITUTION OF BRUNEI DARUSSALAM\n\nPROCLAMATION OF EMERGENCY HIS MAJBSTY mB SULTAN\n\nAND YANG DI-PBRTUAN\n\nBRUNBI DARUSSALAM In the name of Allah, the Compassionate, the Merciful, PRAISE be to ALLAH, the Lord of the Universe, and may the benediction and peace of ALLAH be upon Our Leader Muhammad and upon all his Relations and Friends. WHEREAS it is provided under section 83 of the Constitution of Brunei Darussalam, that whenever it appears to His Majesty The Sultan and Yang Di-Pertuan that an occasion of public danger exists whereby the security or economic life of the State, or any part thereof, is threatened, whether by war or external aggression or internal disturbance, actual or threatened, he may by Proclamation declare a state of emergency either in the whole State or in such part of the State as may be specified in the Proclamation ;\n\nBRUNEI DARUSSALAM GOVERNMENT GAZETTE AND WHEREAS on the 14th day of Rabiulawal, the Hijrah of the Prophet (on whom be the benediction and peace of ALLAH) one thousand four hundred and seventeen corresponding to the 30th day of July, one thousand nine hundred and ninety six of the Christian era, we did DECLARE AND PROCLAIM a state of emergency in the whole State of Brunei Darussalam ; AND WHEREAS it is provided under section 83 of the Constitution of Brunei Darussalam that no Proclamation of Emergency shall be in force for more than two years, without prejudice, however, to the issue by His Majesty The Sultan and Yang Di-Pertuan of another such proclamation at or before the end of that period ; AND WHEREAS it appears to us that an occasion of public danger exists whereby the security of the State is threatened ; NOW, THEREFORE, WE, SULTAN HAJI .HASSANAL BOLKIAH MU'IZZADDIN WADDAULAH IBNI AL-MARHUM SULTAN HAJI OMAR 'ALI SAIFUDDIEN SA' ADUL KHAIRI WADDIEN, SOVEREIGN\n\nAND CHIEF OF THE FAMILY ORDER OF THE CROWN OF BRUNEI, Sultan and Yang Di-Pertuan of the State and Territory of Brunei Darussalam and all its Dependencies ; Do hereby DECLARE AND PROCLAIM as of t~is day a state of emergency in the whole State; AND do hereby REVOKE our said recited Proclamation of Emergency done on the 14th day of Rabiulawal, the Hijrah of the Prophet (on Whom be the benediction and peace of ALLAH) one thousand four hundred and seventeen corresponding to the 30th day of July, one thousand nine hundred and ninety six of the Christian era. So be it. Such is the Proclamation of Emergency. May ALLAH, to Whom be praise and Whose name be exalted the King of Kings, vouchsafe His grace and may the Prophet Muhammad (on Whom be the benediction and peace of ALLAH} grant His Blessings to this Proclamation. Amen! 0 Lord of the Universe. Done at the Istana Nurul Iman, Brunei Darussalam, this 3rd day of Rabiulawal the Hijrah of the Prophet {on Whom be the benediction and peace of ALLAH) one thousand four hundred and nineteen corresponding to the 27th day of June, one thousand nine hundred and ninety eight of the Christian era, being the thirty-first year of Our Reign.\n\nBY COMMAND\n\nPENGIRAN HAJJ BAHRIN (Pengiran Laila Kanun Dirajal Minister of Law, Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"PROCLAMATION OF EMERGENCY","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-22-2001-DESCRIPTION-OF-PROOF-COINS-APEC-2000-LOGO-2-139068"] = {"id":"BN-S-22-2001-DESCRIPTION-OF-PROOF-COINS-APEC-2000-LOGO-2-139068","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"APEC 2000 标志 2 与 20 精制币说明","en":"DESCRIPTION OF PROOF COINS APEC 2000 LOGO 2 AND 20 1","orig":null},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22-2001-DESCRIPTION-OF-PROOF-COINS-APEC-2000-LOGO-2-AND-20-1.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22-2001-DESCRIPTION-OF-PROOF-COINS-APEC-2000-LOGO-2-AND-20-1.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-2001-DESCRIPTION-OF-PROOF-COINS-APEC-2000-LOGO-2-139068-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"~ .... No. S22 CURRENCY ACT (CHAPTER 32) (Section 12) Pursuant to section 12(2) of the Currency Act (Chapter 32), it is hereby notified for general information that the denominations and characteristics of the Silver (ingot) Proof and Cupronikel Proof coins to be issued by Brunei Currency Board on 19th. February, 2001 are as shown hereunder -\n\nPROOF COINS DENO· COMPOSITION WEIGHT DIAMETER THICKNESS DESIGN OF OBVERSE DESIGN OF REVERSE\n\nMINATION $20 Silver 999 62.20gm 65mmX31 mm 3.00mm The potrait of His Majesty The Sultan Haji APECLogo Hassanal Bolkiah Mu'izzaddin Waddaulah Sultan and Yang Di-Pertuan of Brunei Darussalam. Negara Brunei Darussalam's APEC 2000 Logo. -~~~ $2 Cupronickel 9.80gm 27.30mm 1.90mm The potrait of His Majesty The Sultan Haji Negara Brunei Hassanal Bolkiah Mu'izzaddin Waddaulah Darussalam's APEC Sultan and Yang Di-Pertuan of Brunei 2000 Logo .... Darussalam. ~ ~ == Date: 19th. February, 2001 DATO SERI PADUKA AWANG HAJI SELAMAT BIN HAJI MUNAP for Chairman, Brunei Currency Board. 8 t-.) ~ ,"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"DESCRIPTION OF PROOF COINS APEC 2000 LOGO 2 AND 20 1","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013"] = {"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":12,"structureMode":"SECTION","title":{"zh":"海关裁定条例 2013","en":"CUSTOMS CUSTOMS RULINGS REGULATIONS 2013","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013.pdf》（6 页），本次切分 12 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Customs (Customs Rulings) Regulations, 2013 and shall commence on the same date as the Customs (Amendment) Order, 2013. Application for customs ruling."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"(1) Subject to sub-regulation (3), any person concerned in the importation of any goods may apply to the Controller for a ruling on one or more of the following matters {a} the classification of goods; {b} the country of origin of the goods; {c} the application of a provision of the Customs (Valuation of Imported Goods) Rules, 2001 (S 53/2001) to the goods. (21 Where any goods are the subject of any Free Trade Agreement to which Brunei Darussalam is a party, and that Free Trade Agreement identifies the person who may apply for a ruling in relation those goods, only that person may apply under sub-regulation (l~·or (2) for a ruling in relation to those goods.\n\n(3) An application for a ruling shall {a} be made in such form as the Controller may determine; (b} comply with the disclosure requirements of regulation 5; and {c} be made at such time as the Controller may determine."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"Controller may decline to make ruling. •"},"text":{"en":"( 1) The Controller may decline to make a ruling if {a} the application for the ruling would require the Controller to determine any question of fact; {bf the Controller considers that the correctness of the ruling would depend on the making of assumptions, whether in respect of a future event or any other matter; {cf the application is frivolous or vexatious; {d) the matter on which the ruling is sought involves the interpretation of any foreign law; {e} after the Controller has requested further information\n\n(i) the applicant fails to provide the information within the time specified by the Controller for the provision of the information; or\n\n(ii) in the Controller's opm10n, the applicant has not provided sufficient information in relation..to the application; {f} an appeal under these Regulations involving the subject-matter referred to in the application is pending.\n\n(2) The Controller shall, where he has declined to make a ruling, notify the applicant in writing of his decision and the reasons therefor. Duration of ruling."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"A ruling shall apply in relation to a matter only for such period as may be stated in the ruling. Information to be provided to Controller."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(1) An application for a ruling shall {a} identify the applicant; and (b} disclose all relevant facts and documents relating to the matter in respect of which the ruling is sought.\n\n(2) The Controller may, at any time, request further information from an applicant for the purpose of making a ruling.\n\n(3) An applicant for a ruling shall provide the Controller with the information referred to in sub-regulation (2) within such time as the Controller may determine. Controller may make assumptions."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"If the Controller considers that the correctness of a ruling would depend on assumptions being made about any future event or other matter, the Controller may make the assumptions that he considers to be most appropriate. Making of ruling."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(1) A ruling made by the Controller shall state(a) that it is a ruling made under section 22A;\n\n(b) the identity of the person or class of persons to whom, and the particulars of the matters to which, the ruling applies;\n\n(c) any material assumptions about the future events or other matters made by the Controller; and\n\n(d) the conditions (if any) applicable to the ruling.\n\n(2) The Controller shall notify the person to whom the ruling applies of the making of the ruling by sending him a copy of the ruling.\n\n(3) Where there is any Free Trade Agreement applicable to the matter to which a ruling applies, and the Free Trade Agreement specifies the period within which the ruling shall be made, the Controller shall make the ruling within that period.\n\n(4) The Controller may make a ruling notwithstanding that no application has been made under sub-regulation 1. Modification or withdrawal of ruling."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"(1) The Controller may, on his discretion or on application of a person to whom a ruling applies, at any time, modify or withdraw a ruling by notifying the person to whom the ruling applies in such manner as the Controller may determine of the modification or withdrawal and the reasons therefor. (2! Subject to sub-regulations (3) and (4), a ruling is modified or withdrawn from the date specified in the notice of modification or withdrawaC as the case maybe. !3) The Controller may, on the application of a person to whom a ruling applies, postpone the date the ruling is modified or withdrawn to such later date as the Controller may determine, if that person shows that\n\n(a) he had relied in good faith on the ruling; and {bJ the modifications and withdrawal, as the case may be, of the ruling would be detrimental to him.\n\n(4) The Controller may postpone the date the ruling is modified or withdrawn to such later date as he may determine notwithstanding that no application has been made under sub-regulation (3). (5} If the Controller withdraws a ruling, the ruling shall not apply in relation to any goods, the subject-matter of the ruling, which are imported or manufactured locally, on or after the date of the withdrawal. (6} If {a} the Controller withdraws a ruling made pursuant to application by a person under regulation 1; and {b) the person to whom the ruling applies has not acted in accordance with any condition applicable to the ruling, the ruling shall cease to apply to that person in relation to any goods, the subjectmatter of the ruling, which are imported or manufactured locally before the date of the withdrawal.\n\n(7) If the Controller modifies a ruling, the modified ruling shall apply in relation to any goods, the subject-matter of the modified ruling, which are imported or manufactured locally, on or after the date of the modification. (8} If{a} the Controller modifies a ruling made pursuant to an application by a person under sub-regulation 1; and {b) the person to whom the original ruling applies has not acted in accordance with any condition applicable to the original ruling, the modified ruling shall apply to that person in relation to any goods, the subject-matter of the modified ruling, which are imported or manufactured locally, before the date of modification.\n\n(9) The Controller may modify or withdraw a ruling if {a) the ruling is based on an error of fact; {b) there is a change in the circumstances after the ruling was made; {c) any information provided by the applicant in support of his application for the ruling is false, inaccurate or misleading;\n\n(d) there is a change in the basis of the classification of the goods after the ruling was made; {e) there is a change in the circumstances relating to the sale and import or local manufacture of goods after the ruling was made; {f) an offence is suspected to have been committed in relation to the goods; or\n\n(g) it is one of the grounds of modification or withdrawal provided under any Free Trade Agreement applicable to the matter to which the ruling applies. Typographical or minor error in ruling."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Controller does not have to withdraw and re-issue a ruling to correct any typographical or minor error, if the correction does not change the meaning of the ruling. Application of ruling if S 39/2006 amended."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A ruling does not apply from the date a provision of the Customs Order, 2006 is repealed or amended to the extent that the repeal or amendment changes the way the provision applies in the ruling. Controller to declare rulings void."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Controller shall by a notice declare a customs ruling made under section 22A to be void and of no effect if the ruling has been obtained by the applicant by way of fraud, misrepresentation or falsification of facts. Receiving two customs rulings."}},{"id":"BN-S-22-2013-CUSTOMS-CUSTOMS-RULINGS-REGULATIONS-2013-A12","no":12,"noLabel":{"en":"Section 12."},"heading":{"en":"iS 39/2006)"},"text":{"en":"Where an applicant receives two or more different customs ruling on the same subject-matter, such rulings shall be treated as being void and such applicant shall immediately notify the Controller who shall, within 30 days from the date of the notification, issue a new customs ruling. Made this 9th. day of Jamadilawal, 1434 Hijriah corresponding to the 21st. day of March, 2013. PEHIN ORANG KA YA LAlLA SETIA\n\nDATO SERI SETIA A WANG HAJI ABDUL RAHMAN\n\nBIN HAJI IBRAHIM, Minister of Finance II, Office of the Prime Minister. Dicetak oleh PENGIRAN HAJI ZAINAL ABIDIN BIN PENGIRAN SERI WIJAYA PENGIRAN HAJI AHMAD, Pengarah Percetakan, di Jabatan Percetakan Kerajaan, Bandar Seri Begawan BB3510, Negara Brunei Darussalam. Harga B$5.00"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CUSTOMS CUSTOMS RULINGS REGULATIONS 2013","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37"] = {"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":6,"structureMode":"SECTION","title":{"zh":"所得税丹麦王国信息交换命令 2014","en":"INCOME TAX EXCHANGE OF INFORMATION KINGDOM OF DENMARK ORDER 2014","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22_2015_E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDOM-OF-DENMARK-ORDER-2014.pdf》（10 页），本次切分 6 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22_2015_E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDOM-OF-DENMARK-ORDER-2014.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"The taxes which are the subject of this Agreement are taxes of every kind"},"text":{"en":"For the purposes of this Agreement, unless otherwise defined: {a} the term \"Contracting Party\" means Brunei Darussalam or Denmark as the context requires; (bJ the term \"Brunei Darussalam\" means the territory of Brunei Darussalam including its territorial sea, extending to the airspace above such territory, over which it exercises sovereignty, and the maritime area beyond its territorial sea, including ·sea-bed and subsoil, which has been or may hereafter be designated under the laws of Brunei Darussalam as an area over which it exercises sovereign rights and jurisdiction in accordance with international law; (cJ the term \"Denmark\" means the Kingdom of Denmark including any area outside the territorial sea of Denmark which in accordance with international law has been or may hereafter be designated under Danish laws as an area within which Denmark may exercise sovereign rights with respect to the exploration and exploitation of the natural resources of the sea-bed or its subsoil and the superjacent waters and with respect to other activities for the exploration and economic exploitation of the area; the term does not comprise the Faroe Islands and Greenland; (dJ the term \"competent authority\" means: !i) in Brunei Darussalam, the Minister of Finance or his authorised representative; jii) in Denmark, the Minister for Taxation or his authorized representative;\n\n(e) the term \"person\" includes an individual, a company and any other body of persons; {f) the term \"company\" means any body corporate or any entity that is treated as a body corporate for tax purposes;\n\n(g) the term \"publicly traded company\" means any company whose principal class of shares is listed on a recognised stock exchange provided its listed shares can be readily purchased or sold by the public. Shares can be purchased or sold \"by the public\" if the purchase or sale of shares is not implicitly or explicitly restricted to a limited group of investors;\n\n(h) the term \"principal class of shares\" means the class or classes of shares representing a majority of the voting power and value of the company;\n\n(i) the term \"recognised stock exchange\" means any stock exchange agreed upon by the competent authorities of the Contracting Parties;\n\n(j) the term \"collective investment fund or scheme\" means any pooled investment vehicle, irrespective of legal form. The term \"public collective investment fund or scheme\" means any collective investment fund or scheme provided the units, shares or other interests in the fund or scheme can be readily purchased, sold or redeemed by the public. Units, shares or other interests in the fund or scheme can be readily purchased, sold or redeemed \"by the public\" if the purchase, sale or redemption is not implicitly or explicitly rest'ricted to a limited group of investors; (k} the term \"tax\" means any tax to which the Agreement applies;\n\n(l) the term \"applicant Party\" means the Contracting Party requesting information;\n\n(m) the term \"requested Party\" means the Contracting Party requested to provide information;\n\n(n) the term \"information gathering measures\" means laws and administrative or judicial procedures that enable a Contracting Party to obtain and provide the requested information;\n\n(o) the term \"information\" means any fact, statement or record in any form whatever; 28th. 2015 [p) the term ··criminal tax matters\" means tax matters involving intentional conduct which is liable to prosecution under the criminal laws of the applicant Party; {q} the term \"criminal laws\" means all criminal laws designated as such under domestic law irrespective of whether contained in the tax laws, the criminal code or other statutes."}},{"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"of signature of the Agreement in addition to or in place of the existing taxes. This"},"text":{"en":"As regards the application of this Agreement at any time by a Contracting Party, any term not defined therein shall, unless the context otherwise requires, have the meaning that it has at that time under the law of that Party, any meaning under the applicable tax laws of that Party prevailing over a meaning to the term under other laws of that Party. Article 5 Exchange of Information Upon Request"}},{"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"If specifically requested by the competent authority of an applicant Party, the competent authority of the requested Party shall provide information under this Article, to the extent allowable under its domestic laws, in the form of depositions of witnesses and authenticated copies of original records."}},{"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Each Contracting Party shall ensure that its competent authorities for the purposes specified in Article 1 of the Agreement, have the authority to obtain and provide upon request: {a} information held by banks, other financial institutions, and any person acting in an agency or fiduciary capacity including nominees and trustees; {b) information regarding the ownership of companies, partnerships, trusts, foundations, \"Anstalten\" and other persons, including, within the constraints of Article 2, ownership information on all such persons in an ownership chain; in the case of trusts, information on settlers, trustees and beneficiaries; and in the case of foundations, information on founders, members of the foundation council and beneficiaries. Further, this Agreement does not create an obligation on the Contracting Parties to obtain or provide ownership information with respect to publicly traded companies or public collective investment funds or schemes unless such information can be obtained without giving rise to disproportionate difficulties."}},{"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The competent authority of the applicant Party shall provide the following information to the competent authority of the requested Party when making a request for information under the Agreement to demonstrate the foreseeable relevance of the information to the request: (a} the identity of the person under examination or investigation;\n\n(b) a statement of the information sought including its nature and the form in which the applicant Party wishes to receive the information from the requested Party; (c} the tax purpose for which the information is s<?ught; (d} grounds for believing that the information requested is held in the requested Party or is in the possession or control of a person within the jurisdiction of the requested Party; (e} to the extent known, the name and address of any person believed to be in possession of the requested information; (f} a statement that the request is in conformity with the law and administrative practices of the applicant Party, that if the requested information was within the jurisdiction of the applicant Party then the competent authority of the applicant Party would be able to obtain the information under the laws of the applicant Party or in the normal course of administrative practice and that it is in conformity with this Agreement;\n\n(g) a statement that the applicant Party has pursued all means available in its own territory to obtain the information, except those that would give rise to disproportionate difficulties."}},{"id":"BN-S-22-2015-E-INCOME-TAX-EXCHANGE-OF-INFORMATION-KINGDO-0C7F37-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The competent authority of the requested Party shall forward the requested information as promptly as possible to the applicant Party. To ensure a prompt response, the competent authority of the requested Party shall: (a} Confirm receipt of a request in writing to the competent authority of the applicant Party and shall notify the competent authority of the applicant Party of deficiencies in the request, if any, within 60 days of the receipt of the request. (b} If the competent authority of the requested Party has been unable to obtain and provide the information within 90 days of receipt of the request, 28th. APRIL 2015 including if it encounters obstacles in furnishing the information or it refuses to furnish the information, it shall immediately inform the applicant Party, explaining the reason for its inability, the nature of the obstacles or the reasons for its refusal. Article 6 Tax Examinations Abroad"}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"INCOME TAX EXCHANGE OF INFORMATION KINGDOM OF DENMARK ORDER 2014","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-22-2016-NOTIFICATION-OF-COMMENCEMENT"] = {"id":"BN-S-22-2016-NOTIFICATION-OF-COMMENCEMENT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"生效公告","en":"NOTIFICATION OF COMMENCEMENT","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22-2016-NOTIFICATION-OF-COMMENCEMENT.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22-2016-NOTIFICATION-OF-COMMENCEMENT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-2016-NOTIFICATION-OF-COMMENCEMENT-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"16th. APRIL, 2016 No. S 22\n\nINSOLVENCY ORDER, 2016 !S 1/2016) Notification of commencement In exercise of the power conferred by section 1(1) and (2) of the Insolvency Order, 2016, the Minister of Finance, with the approval of His Majesty the Sultan and Yang Di-Pertuanl hereby appoints 1st March 2016 as the date on which that Order shall be deemed to have commenced! with the exception of the provisions as set out in the Schedule hereto\n\nSCHEDULE\n\nPROVISIONS OF INSOLVENCY ORDER, 2016 Part VIII section 246(c} (references to '1\\velfth Schedule and Fourteenth Schedule of the Companies Act (Chapter 39)). Dated this 3rd. day of Rejab, 1437 Hijriah corresponding to the 11th. day of April, 2016.\n\nAWANG AHMADDIN BIN HAJI ABDUL RAHMAN Permanent Secretary, Ministry of Finance, Brunei Darussalam."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"NOTIFICATION OF COMMENCEMENT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-22-2019-NOTIFICATION-OF-COMMENCEMTN"] = {"id":"BN-S-22-2019-NOTIFICATION-OF-COMMENCEMTN","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"生效公告","en":"NOTIFICATION OF COMMENCEMTN","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22-2019-NOTIFICATION-OF-COMMENCEMTN.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22-2019-NOTIFICATION-OF-COMMENCEMTN.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-2019-NOTIFICATION-OF-COMMENCEMTN-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"10th. AUGUST, 2019 I No. S 22\n\nCOMPETITION ORDER, 2015 [S 1 I20 15) Notification of commencement i In furtherance to the notification of commencement published as No. S 69 in Part I1 of the Government Gazette dated 23rd August 2017, in exercise of the power conferred by section l(1) and (2) of the Competition Order, 2015, the Minister in the Office of the Prime Minister and Minister of Finance and Economy 11, with the approval of His Majesty the Sultan and Yang Di-Pertuan, '~ hereby appoints 1st January 2020 as the date of commencement for the provisions ~ of that Order as set out in the Schedule hereto - i\n\nSCHEDULE\n\nPROVISIONS OF COMPETITION ORDER, 2015 PART I11 (Chapters 1, 2 and 6)\n\nPART IV PART VI [sections 64 to 74)\n\nPART V THIRD SCHEDULE (provisions in reference to section 11 prohibition) Dated this 9th. day of Zulhijjah 1440 Hijriah corresponding to the 10th. day I of August, 2019. DR. HAJAH MAY FA'EZAH BINTI HAJI AHMAD ARIFFIN Permanent Secretary, Ministry of Finance and Economy."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"NOTIFICATION OF COMMENCEMTN","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C"] = {"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":8,"structureMode":"SECTION","title":{"zh":"文莱达鲁萨兰国宪法修正命令 2021","en":"CONSTITUTION OF BRUNEI DARUSALAM AMENDMENT ORDER 2021","orig":null},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-ORDER-2021.pdf》（5 页），本次切分 8 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-ORDER-2021.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"Amendment of Article 2 of Cons!. I"},"text":{"en":"Article 2 of the Constitution of Brunei Darussalam. in this Order referred to as the Constitution. is amended -\n\n(a) by deleting the definition of \"Deputy Sultan and Yang Di-Pertuan\" and by substituting the following new definition therefor·· \"Deputy Sultan\" means the person appointed by His Majesty the Sultan and Yang Di-Pertuan under section 17 of the Succession and Regency Proclamation. 1959;'\";\n\n(b) by deleting the definition of\" \"His Majesty\" or \"His Majesty the Sultan and Yang Di-Pertuan\" .. and by substituting the following new definition therefor··\"His Majesty\" or \"His Majesty the Sultan and Yang Di-Pertuan\" means(a) a Sultan whose accession to the throne has been proclaimed whether or not he has been crowned as the Sultan and Yang Di-Pertuan. irrespective of whether a declaration has been made and confirmed under section 12 of the Succession and Regency Proclamation, 1959 that by reason ofinfinnity of mind or body he is for the time being incapable of performing the State functions:\n\n(b) his lawful Successor listed in. referred to or contemplated by subsections (2). (3) and (4) of section 3 of the Succession and Regency Proclamation, 1959 or a Regent or a Council of Regency appointed by virtue of or under section II. I 2. 13 or 17 of the Succession and Regency Proclamation. 1959 for the time being exercising State functions. in relation to any permitted or authorised act: and\n\n(c) to the extent to which a Deputy to His Majesty the Sultan and Yang Di-Pertuan is pennitted or authorised to act by His Majesty the Sultan and Yang Di-Pertuan, that Deputy in relation to that pennitted or authorised act;\";\n\n(c) by inserting the following new definition immediately after the definition of ''pension rights\"- .. \"person of the blood of the Sultans of Brunei Darussalam\" means a person who is a lawfully begotten descendant of Al-Marhum Sultan Mohamed Jamalul-alam or. if there is no such male descendant, a person who is a lawfully begotten descendant of the grandfather in the male line of the reigning Sultan or, if there is no reigning Sultan, a lawfully begotten descendant of the grandfather in the male line of the last reigning Sultan:'';\n\n(d) by inserting the following new definition immediately after the definition of ''Standing Orders\" - .. \"State functions\" means tl1e powers, authorities and privileges vested in His Majesty the Sultan and Yang Di-Pertuan by this Constitution, by any other written law or by virtue of His Majesty the Sultan and Yang Di-Pertuan's prerogative:''."}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"Amendment of Article 5"},"text":{"en":"Article 5 of the Constitution is amended, in Clause (2){a). by deleting \"and Yang Di-Pertuan\"."}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"Amendment of Article 6"},"text":{"en":"Article 6 of the Constitution is amended by inserting the following new Clause immediately after Clause (I)- \"( lA) Save for His Majesty the Sultan and Yang Di-Pertuan, the lawful Successor declared under subsection (2) of section 3 of the Succession and Regency Proclamation, 1959, the Deputy Sultan and the Regent, any Member of the Privy Council who is a person of the blood of the Sultans of Brunei Darussalam shall not attend or in any way participate in any meeting or part of the meeting dealing with any issue or matter involving. arising from. relating to. or in connection with. succession or of the provisions of any written law or custom relating to succession including. but not limited to, any matter relating to the receipt of the declamtions referred to in subsection (I) of section 12 of the Succession and Regency Proclamation, 1959, and the appointment of the Council of Regency under the Succession and Regency Proclamation, 1959.\"."}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"Amendment of Article 7"},"text":{"en":"Article 7 of the Constitution is amended by deleting Clause (I) and by substituting the following new Clause therefor··(I) The Privy Council shall not be summoned except by the authority of His Majesty the Sultan and Yang Di-Pertuan or. if His Majesty the Sultan and Yang Di-Pertuan is not present in Brunei Darussalam, the lawful Successor declared under subsection (2) of section 3 ofthe Succession and Regency Proclamation, 1959 if he is present in Brunei Darussalam, or in his absence, if a Council of Regency has been appointed, by the senior male Regent.\"."}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A6","no":6,"noLabel":{"en":"Section 6."},"heading":{"en":"Amendment of Article 8"},"text":{"en":"Article 8 of the Constitution is amended by deleting Clause (2) and by substituting the following new Clause therefor\"(2) In the absence of His Majesty the Sultan and Yang Di-Pertuan, the person who shall preside shall be in the following priority - Ia) the lawful Successor declared under subsection (2) of section 3 of the Succession and Regency Proclamation, 1959 if he is present in Brunei Darussalam:\n\n(b) if such an appointment has been made, the Deputy Sultan:\n\n(c) if the lawful Successor declared under subsection (2) of section 3 of the Succession and Regency Proclamation, 1959 is absent and no Deputy Sultan has been appointed and a Council of Regency has been appointed. the senior male Regent present:\n\n(d) if the lawful Successor declared under subsection (2) of section 3 of the Succession and Regency Proclamation, 1959 is absent. no Deputy Sultan has been appointed and no Council of Regency has been appointed, such Member of the Privy Council as His Majesty the Sultan and Yang Di-Pertuan may appoint: and\n\n(e) in any other case. the ex-oj)icio Member of the Privy Council present who stands first in the order in which those officers are referred to in paragraph (c! of Clause (2) of Article 5:·."}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A7","no":7,"noLabel":{"en":"Section 7."},"heading":{"en":"Amendment of Article 84"},"text":{"en":"Article 84 of the Constitution is amended(a) in Clause (2). by inserting ··. privileges. immunities. rights and other powers\" immediately after \"powers\" in the second line:\n\n(b) by adding the following new Clause''(3) For the avoidance of doubt. all the prerogative powers. privileges. immunities, rights and other powers and jurisdiction that His Majesty the Sultan and Yang Di-Pertuan had. exercised and enjoyed, whether under this Constitution, the Succession and Regency Proclamation, 1959 or the laws of Brunei Darussalam (written laws or otherwise), before the commencement of the Constitution of Brunei Darussalam (Amendment) Order, 2021 and the Succession and Regency (Amendment) Proclamation. 202 I remain unaffected and shall continue in full force and effect.\". Amendment of Article 848"}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A8","no":8,"noLabel":{"en":"Section 8."},"heading":{"en":"Amendment of Article 84B"},"text":{"en":"Article 84B of the Constitution is amended by deleting Clause (I) and by substituting the following new Clause therefor\"(I) His Majesty the Sultan and Yang Di-Pertuan is inviolable and shall not be liable to any proceedings whatsoever in any court in respect of anything done or omitted to have been done by him during or after his reign in either his personal or official capacity. This immunity is absolute and shall not be set aside.\". Amendment of Article 85"}},{"id":"BN-S-22-2021-CONSTITUTION-OF-BRUNEI-DARUSALAM-AMENDMENT-816F6C-A9","no":9,"noLabel":{"en":"Section 9."},"heading":{"en":"CONSTITUTION OF BRUNEI DARUSSALAM (AMENDMENT) ORDER, 2021"},"text":{"en":"Article 85 of the Constitution is amended - (a} by deleting Clause (3 ):\n\n(b) by deleting Clause ( 4 ):\n\n(c) by deleting Clause (5). Made this 26th. day of Muharram. 1443 Hijriah corresponding to the 4th. day of September, 202 I at Our Istana Nurul !man. Bandar Seri Begawan. Brunei Darussalam.\n\nHIS MAJESTY\n\nTHE SULTAN AND YANG 01-PERTUAN, BRUNEI DARUSSALAM."}}],"pack":"bn-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CONSTITUTION OF BRUNEI DARUSALAM AMENDMENT ORDER 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
